// Casi clinici simulati: dati. Ogni caso: id unico, d = sezione (chiave di DC), t = titolo SENZA diagnosi, chips, testo di presentazione,
// diag = diagnosi del caso (mostrata solo nella Revisione), schede = [id, nome] delle schede collegate,
// items = reperti: c = aspetto (0 Anamnesi, 1 Ispezione, 2 Sensibilità, 3 Dolore, 4 Mobilità, 5 Forza, 6 Funzione, 7 Test specifici, 8 Imaging),
// l = voce, t = reperto, k = voce importante, w = perché conta, s = fonte (solo fonti già presenti nella scheda), a = sinonimi per il controllo automatico.
// I valori numerici dei reperti sono inventati ma realistici.
const CASI=[
{"id":"caviglia-ruck","d":"Caviglia","t":"Flanker, 26 anni, caviglia dopo una ruck","chips":["26 anni","Flanker (7)","Serie A2","1,86 m · 98 kg","Caviglia destra"],"testo":"Luca è un terza linea flanker di serie A2. Domenica, nel secondo tempo, durante una ruck aveva il piede destro piantato a terra quando un avversario gli è caduto sulla parte esterna della gamba. È uscito aiutato dai compagni e non è riuscito a riprendere a correre. Ha messo ghiaccio e il medico della società in panchina gli ha detto «distorsione di caviglia». Non ha fatto esami. Oggi è martedì e viene da te: entra camminando, zoppica un po' sulla destra.","diag":"Lesione della sindesmosi tibio-peroneale distale destra, stabile (West Point IIa): rottura completa del legamento tibio-peroneale anteriore, distrazione parziale della membrana interossea, legamento posteriore e deltoide integri, nessuna frattura (Maisonneuve esclusa). Derby a 12 giorni non realistico: rientro guidato dai criteri.","schede":[["caviglia-sindesmosi","Lesione della sindesmosi"]],items:[
{"c":0,"l":"Meccanismo del trauma","t":"«Ero in ruck, piede destro piantato, peso tutto sulla destra. Un avversario è crollato sul lato esterno della mia gamba, sotto il ginocchio. Il piede è rimasto bloccato a terra, la gamba è andata verso l'interno e il piede si è girato verso l'esterno con la punta spinta in su. Non mi sono girato io, è successo di colpo.»","k":1,"w":"Rotazione esterna con dorsiflessione forzata a piede bloccato è il meccanismo classico della sindesmosi: orienta l'ipotesi prima dei test.","a":"come ti sei fatto male dinamica"},
{"c":0,"l":"Cosa è stato avvertito al momento","t":"«Dolore forte davanti, sopra la caviglia, 8/10 nei primi secondi. Forse uno strappo o uno schiocco, ma con la ruck addosso non so dirlo. Non ho sentito la caviglia cedere di lato.»","a":"schiocco dolore iniziale"},
{"c":0,"l":"Capacità di camminare dopo il trauma","t":"«Tre o quattro passi zoppicando, sostenuto da un compagno. Da solo, senza aiuto, non ci sono riuscito: appena caricavo dovevo sollevare il piede.»","k":1,"w":"Serve alle Ottawa Ankle Rules (4 passi) e dà un'idea della gravità del danno.","a":"ottawa passi appoggio"},
{"c":0,"l":"Sede del dolore","t":"«Davanti, sopra l'articolazione, dove la gamba incontra il piede. Sul lato esterno ho solo un fastidio più leggero.»","k":1,"w":"Il dolore anteriore sopra la rima è diverso da quello della distorsione laterale e orienta verso la sindesmosi.","a":"dove fa male localizzazione"},
{"c":0,"l":"Andamento da domenica","t":"«Domenica sera 8/10. Oggi a riposo 2/10; scendendo le scale, spingendo sull'avampiede o camminando veloce arrivo a 5/10.»","a":"miglioramento vas nrs peggioramento"},
{"c":0,"l":"Dolore notturno","t":"«No, dormo bene. Mi dà fastidio solo se mi giro nel letto e il piede si muove di colpo verso l'esterno.»","a":"sonno notte"},
{"c":0,"l":"Gonfiore e ecchimosi riferiti","t":"«La caviglia è gonfia davanti e un po' di lato. Dopo domenica sera è uscito un livido piccolo sul lato esterno, non nero come nelle altre storte.»","a":"edema livido"},
{"c":0,"l":"Distorsioni e infortuni precedenti","t":"«Due distorsioni alla stessa caviglia destra, di quelle con il piede girato verso l'interno. L'ultima circa due anni fa: ghiaccio e riposo qualche giorno, nessuna fisioterapia né esami. Da allora a volte la sentivo molle sui terreni sconnessi.»","k":1,"w":"Due distorsioni laterali non riabilitate fanno pensare a instabilità cronica: cambia la prevenzione e il rischio di recidiva.","a":"storia pregressa"},
{"c":0,"l":"Farmaci","t":"«Anti-infiammatori da domenica, nient'altro.»","a":"fans terapia"},
{"c":0,"l":"Salute generale e sintomi sistemici","t":"«Nessuna altra malattia. Niente febbre, perdita di peso o dolori notturni altrove.»","a":"red flag febbre"},
{"c":0,"l":"Ruolo, carichi e calendario","t":"«Flanker, quattro allenamenti a settimana più la partita. Il derby è tra 12 giorni e il mister conta su di me.»","a":"allenamento partita derby"},
{"c":0,"l":"Lavoro","t":"«Magazziniere: sto in piedi quasi tutto il giorno, cammino nel magazzino e a volte sollevo scatoloni da 10-15 kg.»","a":"occupazione"},
{"c":0,"l":"Cosa è stato fatto finora","t":"«Ghiaccio subito. Il medico della società mi ha detto che è una distorsione. Nessun esame e nessun tutore.»","a":"trattamenti precedenti medico"},
{"c":1,"l":"Ispezione statica, supino","t":"Gonfiore moderato anterolaterale a destra, sopra e davanti alla rima articolare; a sinistra assente. Ecchimosi modesta e diffusa sul lato laterale, nessuna mediale. Nessuna deformità. Pelle integra. Profilo di Achille e malleoli meno definito a destra per l'edema.","k":1,"w":"L'edema anteriore e l'ecchimosi esclusivamente laterale sono segni utili per indirizzare la diagnosi."},
{"c":1,"l":"Ispezione statica, prono","t":"Posteriormente nessun edema significativo. Tendine d'Achille regolare, calcagno in asse e simmetrico alla sinistra.","a":"dietro retropiede"},
{"c":3,"l":"Palpazione dei malleoli (bordo posteriore e punta)","t":"Bordo posteriore e punta del malleolo laterale: non dolenti. Bordo posteriore e punta del malleolo mediale: non dolenti.","k":1,"w":"Fa parte delle Ottawa Ankle Rules: serve a decidere se serve la radiografia per escludere una frattura.","a":"ottawa ossa"},
{"c":3,"l":"Palpazione di base del 5° metatarso e navicolare","t":"Base del 5° metatarso: non dolente. Navicolare: non dolente.","k":1,"w":"Completa le Ottawa Ankle Rules per il medio piede.","a":"ottawa piede"},
{"c":3,"l":"Palpazione di testa e diafisi prossimale del perone","t":"Testa e diafisi prossimale: non dolenti alla palpazione.","k":1,"w":"Dolore prossimale con trauma in rotazione fa sospettare una frattura di Maisonneuve: va sempre escluso.","a":"maisonneuve ginocchio"},
{"c":3,"l":"Palpazione del perone distale e della zona sopra la rima","t":"Diafisi distale, nel tratto anteriore sopra la rima articolare: dolore chiaro per circa 6 cm sopra la linea articolare.","k":1,"w":"L'estensione del dolore sopra la rima indica coinvolgimento della sindesmosi, non solo dei legamenti laterali."},
{"c":3,"l":"Palpazione del legamento tibio-peroneale anteriore","t":"Dolore marcato davanti e sopra la rima, riproducibile alla palpazione.","k":1,"w":"Palpazione del legamento: test molto sensibile (circa 92%), utile per escludere se negativo.","s":"Sman 2015 (PMID 24255766); Netterström-Wedin 2021 (PMID 33774464)","a":"aitfl sindesmosi legamento"},
{"c":3,"l":"Palpazione del legamento talo-peroneale anteriore","t":"Lieve dolorabilità.","a":"atfl laterale"},
{"c":3,"l":"Palpazione del legamento calcaneo-peroneale","t":"Non dolente.","a":"cfl laterale"},
{"c":3,"l":"Palpazione del legamento deltoideo","t":"Non dolente.","a":"mediale deltoide"},
{"c":3,"l":"Palpazione del tendine d'Achille","t":"Non dolente, senza gap né nodulo.","a":"tendine tricipite"},
{"c":1,"l":"Misurazione del gonfiore (figura a 8)","t":"Destra 54,0 cm, sinistra 51,5 cm. Differenza 2,5 cm. Misura ripetuta due volte con valori uguali.","a":"edema misura circonferenza"},
{"c":1,"l":"Termotatto","t":"Destra leggermente più calda a livello anterolaterale. Parte mediale e lato sinistro a temperatura simile."},
{"c":1,"l":"Segni di trombosi venosa profonda","t":"Polpaccio morbido, non gonfio e non caldo. Negativo.","a":"tvp polpaccio"},
{"c":2,"l":"Sensibilità superficiale e profonda del piede","t":"Sensibilità normale (tatto e dolore) sul dorso, sulla pianta e sui margini del piede, senza differenze con il lato sinistro.","a":"neurologico dermatomeri"},
{"c":2,"l":"Polsi pedidio e tibiale posteriore","t":"Presenti e simmetrici. Riempimento capillare normale.","a":"vascolare circolo"},
{"c":1,"l":"Esame del ginocchio","t":"Nessun reperto significativo."},
{"c":1,"l":"Esame dell'anca","t":"Nessun reperto significativo."},
{"c":1,"l":"Rachide lombare e sacroiliaca","t":"Nessun reperto significativo."},
{"c":4,"l":"Dorsiflessione passiva (goniometro, ginocchio esteso e flesso)","t":"Ginocchio esteso: destra 6° con dolore anteriore sopra la rima all'ultimo range; sinistra 14° senza dolore. Ginocchio flesso a 90°: destra 10° con dolore anteriore già prima della fine del range; sinistra 22° senza dolore. Fine corsa a destra brusca e dolorosa, con difesa; a sinistra elastica.","k":1,"w":"Misura la limitazione e il tipo di dolore; i due angoli del ginocchio distinguono gastrocnemio e soleo.","a":"rom caviglia"},
{"c":4,"l":"Escursioni attive di caviglia (DF, PF, inversione, eversione)","t":"DF destra 8° con dolore anteriore a metà movimento, sinistra 20°. PF destra 42°, sinistra 48°. Inversione destra 24° con lieve fastidio laterale, sinistra 28°. Eversione destra 10° con dolore anteriore e fastidio laterale, sinistra 14°. Movimento fluido, senza scatti né schiocchi.","a":"attivo movimento"},
{"c":4,"l":"Scivolamento posteriore dell'astragalo","t":"Ridotto e doloroso anteriormente a destra rispetto a sinistra.","a":"accessorio mobilizzazione"},
{"c":5,"l":"Calf raise monopodalico fino a fatica","t":"Destra 5 ripetizioni dolorose (dolore anteriore); sinistra 30.","k":1,"w":"Misura forza e resistenza del tricipite surale; è un valore di partenza per il follow-up e per i criteri di rientro.","a":"heel raise polpaccio tricipite"},
{"c":5,"l":"Forza manuale di inversori ed eversori","t":"Forza conservata con dolore lieve all'eversione.","a":"mmt peronei tibiale"},
{"c":5,"l":"Forza dei dorsiflessori","t":"Forza normale; dolore anteriore lieve contro resistenza.","a":"tibiale anteriore"},
{"c":7,"l":"Compressione di tibia e perone a metà polpaccio","t":"Positivo: dolore sopra la sindesmosi distale, riproduce il sintomo.","k":1,"w":"Test specifico (specificità 85-88%): se positivo conferma il sospetto di sindesmosi.","s":"Sman 2015 (PMID 24255766); Netterström-Wedin 2021 (PMID 33774464)","a":"squeeze"},
{"c":7,"l":"Stress in rotazione esterna (piede extraruotato con tibia stabile)","t":"Positivo: riproduce il dolore anterolaterale sopra la sindesmosi.","k":1,"w":"Test specifico (circa 78%) vicino al meccanismo di lesione.","s":"Netterström-Wedin 2021 (PMID 33774464)","a":"kleiger external rotation extrarotazione"},
{"c":7,"l":"Dorsiflessione con compressione","t":"Positivo: dolore anteriore, che si riduce quando la sindesmosi viene compressa.","k":1,"w":"Segno clinico a favore di una lesione della sindesmosi distale.","s":"Sman 2015 (PMID 24255766)","a":"lunge compressione"},
{"c":7,"l":"Traslazione dell'astragalo nella mortaise","t":"Dolore anteriore; traslazione appena più ampia del lato sano, non netta.","s":"Consenso ESSKA-AFAS (PMID 26704800)","a":"cotton"},
{"c":7,"l":"Traslazione antero-posteriore del perone","t":"Dolore anteriore; traslazione simile al lato sano.","s":"Consenso ESSKA-AFAS (PMID 26704800)","a":"fibular translation"},
{"c":7,"l":"Cassetto anteriore dell'astragalo","t":"Lassità simile al lato controlaterale; dolore lieve.","k":1,"w":"Valuta il legamento talo-peroneale anteriore e aiuta a escludere una distorsione laterale classica.","a":"anterior drawer"},
{"c":7,"l":"Talar tilt","t":"Negativo.","k":1,"w":"Insieme al cassetto, esclude un coinvolgimento importante del legamento calcaneo-peroneale.","a":"inversione stress"},
{"c":7,"l":"Test di Thompson","t":"Negativo: flessione plantare presente alla compressione del polpaccio.","a":"achille rottura"},
{"c":7,"l":"Saltello monopodalico in acuto","t":"Non eseguibile: dolore anteriore sopra la rima.","k":1,"w":"L'incapacità di fare un hop singolo ha sensibilità dell'89% per la lesione della sindesmosi.","s":"Sman 2015 (PMID 24255766)","a":"hop salto"},
{"c":6,"l":"Osservazione statica in piedi","t":"Carico spostato a sinistra, circa 60/40. Gonfiore anterolaterale visibile anche in carico. Arco plantare destro leggermente più basso, retropiede lievemente in valgo. Ginocchia e bacino simmetrici.","a":"postura bipodalica"},
{"c":6,"l":"Appoggio monopodalico (occhi aperti)","t":"Destra 8 secondi, poi appoggia l'altro piede; dolore anteriore, oscillazione evidente della caviglia, compenso con le braccia. Sinistra 30 secondi senza problemi.","k":1,"w":"Misura equilibrio e controllo neuromuscolare: è un riferimento per le fasi e per il rientro.","a":"equilibrio monopodalico single leg stance"},
{"c":6,"l":"Cammino","t":"Appoggio destro accorciato, sgancio del tallone e spinta dell'avampiede ridotti a destra. Piede destro lievemente extraruotato in appoggio. Dolore anteriore 3-4/10 che sale dopo dieci passi. Nessuna stampella, andatura antalgica.","k":1,"w":"L'osservazione del cammino guida le decisioni su carico e supporti nella fase iniziale.","a":"gait deambulazione"},
{"c":6,"l":"Dorsiflessione in carico (lunge al muro)","t":"Destra 4 cm con dolore anteriore; sinistra 12 cm.","k":1,"w":"Test di riferimento per la dorsiflessione in carico, e misura da ripetere nel follow-up.","s":"Netterström-Wedin 2021 (PMID 33774464)","a":"wblt weight bearing lunge"},
{"c":6,"l":"Squat monopodalico","t":"Eseguito parzialmente: sul lato destro riduce la flessione per il dolore anteriore.","a":"single leg squat"},
{"c":6,"l":"Salire e scendere le scale","t":"Salire con dolore 3/10, scendere con dolore 5/10, entrambi davanti sopra la rima."},
{"c":6,"l":"Test di equilibrio dinamico","t":"Non eseguibile oggi per dolore.","a":"y balance"},
{"c":6,"l":"Corsa leggera","t":"Non eseguibile: non tollera la spinta dell'avampiede.","a":"jogging"},
{"c":8,"l":"RX caviglia senza carico (AP, laterale, mortaise)","t":"Nessuna frattura. Spazio tibio-peroneale nei limiti a riposo.","a":"radiografia"},
{"c":8,"l":"RX caviglia sotto carico (AP e mortaise)","t":"Nessuna frattura. Spazio libero tibio-peroneale 4,5 mm (al limite), sovrapposizione normale, spazio mediale normale.","k":1,"w":"La radiografia sotto carico valuta lo spazio tibio-peroneale e la stabilità: il consenso ESSKA-AFAS raccomanda AP e mortaise.","s":"Consenso ESSKA-AFAS (PMID 26704800)","a":"radiografia carico weight bearing"},
{"c":8,"l":"Risonanza magnetica","t":"Rottura completa del legamento tibio-peroneale anteriore, distrazione parziale della membrana interossea, legamento tibio-peroneale posteriore e deltoide integri, edema osseo lieve dell'astragalo anterolaterale, perone prossimale integro.","k":1,"w":"Conferma il danno legamentoso e aiuta a classificare la lesione come stabile o instabile.","a":"rmn risonanza"},
{"c":8,"l":"Ecografia","t":"Edema dei tessuti molli anteriori; legamento tibio-peroneale anteriore non ben valutabile.","a":"ultrasuoni"}
]},
{"id":"inguine-centro","d":"Anca","t":"Centro, 24 anni, dolore all'inguine da settimane","chips":["24 anni","Centro (13)","Serie A2","1,82 m · 88 kg","Inguine destro"],"testo":"Marco è un centro di serie A2. Da circa cinque settimane ha dolore all'inguine destro. È iniziato piano piano durante la preparazione estiva, quando sono aumentati sprint e cambi di direzione. Non ricorda un trauma. Continua ad allenarsi e a giocare, ma il dolore lo condiziona sempre di più. Viene da te un mercoledì, il giorno dopo un allenamento.","diag":"Dolore inguinale correlato agli adduttori a destra (classificazione di Doha), con rotazione interna d'anca ridotta (morfologia cam all'RX), deficit di forza degli adduttori e controllo pelvico ridotto.","schede":[["anca-groin","Dolore inguinale (Doha)"]],items:[
{"c":0,"l":"Esordio e meccanismo","t":"«Nessun trauma preciso. È iniziato in preparazione, quando abbiamo aumentato sprint, cambi di direzione e lavoro con il pallone. All'inizio era solo a fine allenamento.»","k":1,"w":"Esordio graduale legato al carico (sprint, cambi di direzione, calci) è il quadro tipico del dolore inguinale da sovraccarico.","a":"inizio trauma"},
{"c":0,"l":"Sede del dolore","t":"«All'inguine destro, verso l'interno della coscia, vicino all'osso del pube. Ogni tanto si irradia un po' lungo l'interno della coscia.»","k":1,"w":"La sede guida la classificazione di Doha (adduttori, ileopsoas, inguinale, pubica).","s":"Weir 2015 (PMID 26031643)","a":"dove localizzazione"},
{"c":0,"l":"Cosa lo peggiora","t":"«I cambi di direzione, gli sprint, quando calcio con il destro e il giorno dopo gli allenamenti duri. In partita arrivo a 4/10.»","k":1,"w":"I movimenti provocativi indicano quali carichi ridurre senza riposo totale.","a":"aggravanti calcio sprint"},
{"c":0,"l":"Andamento nella giornata e nella settimana","t":"«La mattina rigidità per 10-15 minuti, poi passa. A riposo 2/10 il giorno dopo l'allenamento, quasi zero nei giorni di scarico.»","a":"mattina rigidità"},
{"c":0,"l":"Dolore notturno e sintomi generali","t":"«Di notte dormo bene. Niente febbre, perdita di peso, problemi a urinare o ai testicoli.»","k":1,"w":"Esclude cause non muscolo-scheletriche dell'inguine (urologiche, viscerali, infettive).","a":"red flag notte febbre urine scroto"},
{"c":0,"l":"Tosse e starnuti","t":"«No, tossire o starnutire non mi fa male.»","a":"valsalva ernia"},
{"c":0,"l":"Infortuni precedenti","t":"«Due anni fa una contrattura all'adduttore sinistro, ferma dieci giorni. Mai problemi all'anca.»","a":"storia pregressa"},
{"c":0,"l":"Carico di allenamento","t":"«Quattro allenamenti a settimana più la partita. In preparazione abbiamo fatto molto lavoro di velocità e agilità. Nessun lavoro specifico per gli adduttori.»","k":1,"w":"Picchi di carico e assenza di forza degli adduttori sono fattori su cui intervenire.","s":"Harøy 2019 (PMID 29891614)","a":"volume preparazione"},
{"c":0,"l":"Calcio e lato dominante","t":"«Calcio con il destro, è il mio piede forte.»","a":"dominanza"},
{"c":0,"l":"Farmaci","t":"«Ogni tanto un antinfiammatorio dopo la partita.»","a":"fans"},
{"c":1,"l":"Ispezione in piedi e in posizione supina","t":"Bacino simmetrico, nessun gonfiore o ecchimosi all'inguine, nessuna atrofia evidente della coscia. Nessun rigonfiamento al canale inguinale, nemmeno sotto colpo di tosse.","a":"postura ernia"},
{"c":1,"l":"Cammino","t":"Normale, senza zoppia.","a":"andatura"},
{"c":1,"l":"Rachide lombare e sacroiliaca","t":"Movimenti lombari liberi e indolori. Test provocativi sacroiliaci negativi.","k":1,"w":"Esclude il dolore riferito dalla colonna o dalla sacroiliaca, che può simulare un dolore inguinale.","a":"colonna lombare"},
{"c":2,"l":"Sensibilità di inguine e coscia","t":"Normale e simmetrica, anche nel territorio dell'otturatore e del genitofemorale.","a":"neurologico"},
{"c":2,"l":"Riflessi e forza neurologica","t":"Riflessi rotuleo e achilleo presenti e simmetrici.","a":"riflessi"},
{"c":3,"l":"Palpazione dell'origine dell'adduttore lungo","t":"Dolore riconoscibile all'origine dell'adduttore lungo destro, sul pube: «è proprio quello».","k":1,"w":"Dolore riconoscibile alla palpazione degli adduttori è uno dei due criteri del dolore inguinale adduttore-correlato.","s":"Weir 2015 (PMID 26031643)","a":"adduttore lungo tenderness"},
{"c":3,"l":"Palpazione dell'adduttore breve e gracile","t":"Lieve dolore all'adduttore breve, gracile non dolente.","a":"adduttori"},
{"c":3,"l":"Palpazione della sinfisi pubica","t":"Lieve fastidio, non riconosciuto come il suo dolore.","k":1,"w":"Serve a distinguere il dolore pubico da quello degli adduttori.","s":"Weir 2015 (PMID 26031643)","a":"pube sinfisi"},
{"c":3,"l":"Palpazione dell'ileopsoas","t":"Lieve dolore sotto il legamento inguinale, non riconosciuto come il suo.","k":1,"w":"Esclude o conferma un ileopsoas-correlato, entità di Doha distinta.","s":"Weir 2015 (PMID 26031643)","a":"psoas"},
{"c":3,"l":"Palpazione del canale inguinale","t":"Anello inguinale superficiale non dolente, nessun rigonfiamento alla tosse.","a":"ernia inguinale"},
{"c":3,"l":"Palpazione di grande trocantere e retto addominale","t":"Non dolenti.","a":"trocantere addominali"},
{"c":4,"l":"Rotazione interna dell'anca a 90° di flessione","t":"Destra 20°, sinistra 38°. A destra fine corsa rigido con fastidio all'inguine.","k":1,"w":"Una rotazione interna ridotta è associata al dolore inguinale e orienta verso una componente d'anca da approfondire.","a":"rom intrarotazione"},
{"c":4,"l":"Flessione, extrarotazione e abduzione dell'anca","t":"Flessione destra 115°, sinistra 125°. Extrarotazione 45° e 48°. Abduzione passiva destra 30° con tensione all'interno coscia, sinistra 40°.","a":"rom anca"},
{"c":4,"l":"Test di Thomas","t":"Negativo per la flessione d'anca; lieve tensione del retto femorale a destra.","a":"flessori"},
{"c":5,"l":"Squeeze test a più angoli","t":"Ginocchia estese (0°): dolore 5/10 a destra. Anche a 45°: dolore 6/10. Anche a 90°: dolore 3/10. Forza ridotta rispetto all'atteso.","k":1,"w":"Dolore all'adduzione resistita è il secondo criterio del quadro adduttore-correlato; il valore serve anche da misura per il follow-up.","s":"Weir 2015 (PMID 26031643)","a":"squeeze adduzione"},
{"c":5,"l":"Adduzione resistita in posizione laterale","t":"Destra dolorosa, sinistra indolore.","a":"adduzione"},
{"c":5,"l":"Copenhagen plank a leva corta","t":"Destra 12 secondi con dolore, sinistra 30 secondi.","k":1,"w":"Misura forza e tolleranza degli adduttori al carico eccentrico: valore di partenza e criterio di progressione.","s":"Harøy 2019 (PMID 29891614)","a":"copenhagen"},
{"c":5,"l":"Flessione d'anca resistita","t":"Lieve dolore 2/10 a destra, forza quasi piena.","a":"psoas flessione resistita"},
{"c":5,"l":"Abduzione ed estensione resistite","t":"Forza piena e indolore.","a":"glutei"},
{"c":5,"l":"Ponte monopodalico fino a fatica","t":"Destra 8 ripetizioni, sinistra 15.","a":"single leg bridge"},
{"c":5,"l":"Addominali (crunch resistito)","t":"Indolore.","a":"addome"},
{"c":6,"l":"Squat monopodalico","t":"A destra il ginocchio va verso l'interno e il bacino cade dal lato opposto. A sinistra controllo buono.","k":1,"w":"Il controllo del bacino e del tronco è un obiettivo della riabilitazione attiva.","s":"Hölmich 1999 (PMID 9989713)","a":"single leg squat controllo"},
{"c":6,"l":"Affondo laterale","t":"Dolore all'inguine destro a fine movimento.","a":"lunge laterale"},
{"c":6,"l":"Salti, sprint e cambi di direzione","t":"Non testati in studio. Riferisce dolore 4/10 nei cambi di direzione in allenamento.","a":"sprint cod"},
{"c":6,"l":"Questionario HAGOS","t":"Punteggi ridotti soprattutto nelle sezioni sport e partecipazione.","k":1,"w":"Misura la funzione riferita ed è utile per seguire il percorso.","a":"hagos questionario"},
{"c":7,"l":"FADIR","t":"Positivo a destra: dolore all'inguine.","k":1,"w":"Valuta una componente articolare d'anca: se positivo va approfondito, anche se da solo è poco specifico.","a":"fadir impingement"},
{"c":7,"l":"FABER","t":"Lieve dolore all'inguine a destra, ginocchio a 4 cm in più dal lettino rispetto a sinistra.","a":"faber patrick"},
{"c":7,"l":"Test di Valsalva e tosse","t":"Negativi.","a":"valsalva"},
{"c":7,"l":"Test neurodinamici (slump)","t":"Negativo.","a":"slump neurodinamico"},
{"c":8,"l":"RX del bacino","t":"Nessuna frattura. A destra angolo alfa 62°: morfologia cam.","k":1,"w":"Spiega la rotazione interna ridotta. La morfologia cam è comune anche negli atleti senza sintomi: va interpretata con la clinica.","a":"radiografia"},
{"c":8,"l":"Risonanza magnetica","t":"Lieve edema all'origine dell'adduttore lungo destro, nessuna avulsione o rottura. Lieve edema sotto la cartilagine della sinfisi.","a":"rm rmn"},
{"c":8,"l":"Ecografia","t":"Origine dell'adduttore lungo lievemente ispessita, nessuna lesione.","a":"ecografia"}
]},
{"id":"ginocchio-cambio","d":"Ginocchio","t":"Ala, 22 anni, ginocchio dopo un cambio di direzione","chips":["22 anni","Ala (11)","Serie A2","1,80 m · 84 kg","Ginocchio sinistro"],"testo":"Tommaso è un'ala di serie A2. Sabato, in partita, ha fatto un cambio di direzione di colpo per evitare un placcaggio, senza essere toccato. È caduto, ha sentito il ginocchio sinistro «andare fuori» e non è riuscito a continuare. Oggi è giovedì e viene da te con le stampelle, caricando poco a sinistra.","diag":"Rottura completa del legamento crociato anteriore sinistro senza contatto, con contusione ossea laterale tipica e lesione di I grado del collaterale mediale; menischi integri. Decisione su chirurgia o percorso conservativo da condividere con ortopedico e paziente.","schede":[["lca-ricostruzione","Ricostruzione del LCA"],["lca-conservativo","LCA conservativo"]],items:[
{"c":0,"l":"Meccanismo del trauma","t":"«Ho piantato il piede sinistro per cambiare direzione verso destra, il ginocchio è andato verso l'interno e si è girato. Nessuno mi ha toccato.»","k":1,"w":"Cambio di direzione senza contatto, con valgo e rotazione, è il meccanismo tipico della lesione del LCA.","s":"Koga 2010 (DOI 10.1177/0363546510373570)","a":"come dinamica"},
{"c":0,"l":"Sensazioni al momento","t":"«Ho sentito un rumore, come uno schiocco, dentro il ginocchio, e la sensazione che uscisse e rientrasse.»","k":1,"w":"Schiocco e sensazione di cedimento sono tra i segni anamnestici più suggestivi.","a":"pop schiocco"},
{"c":0,"l":"Tempo di comparsa del gonfiore","t":"«Si è gonfiato tanto nel giro di due o tre ore.»","k":1,"w":"Un gonfiore rapido nelle prime ore fa pensare a un emartro, frequente nella rottura del LCA.","a":"versamento edema"},
{"c":0,"l":"Capacità di continuare a giocare e camminare","t":"«Non sono riuscito a continuare. Sono uscito appoggiandomi a due compagni; da domenica uso le stampelle.»","a":"carico stampelle"},
{"c":0,"l":"Cedimenti e blocchi da allora","t":"«Non mi è più uscito, ma non mi fido a girarmi. Il ginocchio non si è mai bloccato, faccio solo fatica a stenderlo del tutto.»","k":1,"w":"Un vero blocco meccanico (ginocchio bloccato) farebbe sospettare un menisco a manico di secchio da inviare presto all'ortopedico.","a":"blocco cedimento giving way"},
{"c":0,"l":"Dolore","t":"«Adesso 3/10 a riposo, 5/10 se provo a piegarlo o a stenderlo del tutto.»","a":"vas nrs"},
{"c":0,"l":"Infortuni precedenti","t":"«Mai infortuni al ginocchio. Una distorsione di caviglia destra anni fa.»","a":"storia pregressa"},
{"c":0,"l":"Obiettivi e sport","t":"«Voglio tornare a giocare a rugby a questo livello. Gioco all'ala: tanti sprint e cambi di direzione.»","k":1,"w":"Le richieste di pivot e contatto pesano nella decisione condivisa tra chirurgia e percorso conservativo.","s":"Fitzgerald 2000 (PMID 10795668)","a":"obiettivo ritorno"},
{"c":1,"l":"Ispezione del ginocchio","t":"Ginocchio sinistro gonfio, profili ossei meno visibili, nessuna ecchimosi importante. Tiene il ginocchio leggermente flesso.","a":"gonfiore"},
{"c":1,"l":"Stroke test (versamento)","t":"Grado 2+: il liquido torna nella parte mediale prima del secondo passaggio.","k":1,"w":"Quantifica il versamento: grado 0-1 è richiesto per avanzare nella progressione.","s":"Kotsifaki 2023 (PMID 36731908)","a":"versamento stroke effusione"},
{"c":1,"l":"Circonferenza sopra la rotula","t":"Sinistra 2,5 cm in più della destra.","a":"circonferenza"},
{"c":1,"l":"Trofismo del quadricipite","t":"Vasto mediale sinistro meno definito, contrazione lenta.","a":"atrofia"},
{"c":1,"l":"Cammino con stampelle","t":"Carico parziale a sinistra, ginocchio tenuto flesso in tutto l'appoggio, nessuna estensione completa.","a":"andatura"},
{"c":1,"l":"Anca e caviglia","t":"Nessun reperto significativo.","a":"anca caviglia"},
{"c":2,"l":"Sensibilità di gamba e piede","t":"Normale e simmetrica.","a":"neurologico"},
{"c":2,"l":"Polsi distali","t":"Pedidio e tibiale posteriore presenti.","k":1,"w":"Dopo un trauma importante del ginocchio controllare sempre il circolo, soprattutto se si sospetta una lesione multiligamentosa.","a":"vascolare"},
{"c":3,"l":"Palpazione delle rime articolari","t":"Rima laterale lievemente dolente, rima mediale lievemente dolente.","a":"rima menisco"},
{"c":3,"l":"Palpazione del collaterale mediale","t":"Lieve dolore all'inserzione femorale.","a":"mcl collaterale"},
{"c":3,"l":"Palpazione del collaterale laterale e della testa del perone","t":"Non dolenti.","a":"lcl perone"},
{"c":3,"l":"Palpazione di rotula e tendine rotuleo","t":"Non dolenti.","a":"rotula"},
{"c":4,"l":"Estensione e flessione del ginocchio","t":"Estensione: sinistra -5° (non arriva a 0°), destra +3°. Flessione: sinistra 100° con dolore e tensione, destra 145°.","k":1,"w":"Recuperare presto l'estensione completa è una priorità: un deficit che resiste peggiora la ripresa.","s":"Delaloye 2018 (PMID 30013901)","a":"rom estensione flessione"},
{"c":4,"l":"Mobilità della rotula","t":"Ridotta in senso superiore a sinistra.","a":"rotula mobilità"},
{"c":5,"l":"Quadriceps lag test","t":"Lag di 10°: da seduto non arriva a estendere attivamente l'ultimo tratto che raggiunge in passivo.","k":1,"w":"Misura l'inibizione del quadricipite: un lag di 0-5° è richiesto per avanzare.","s":"Kotsifaki 2023 (PMID 36731908)","a":"lag quadricipite"},
{"c":5,"l":"Sollevamento a gamba tesa","t":"Eseguito ma con ginocchio che si piega di qualche grado.","a":"slr"},
{"c":5,"l":"Forza del quadricipite al dinamometro","t":"Non eseguita oggi per il dolore.","a":"dinamometro hhd"},
{"c":5,"l":"Forza di anca e polpaccio","t":"Conservata.","a":"glutei polpaccio"},
{"c":6,"l":"Squat e appoggio monopodalico","t":"Non eseguibili oggi.","a":"squat monopodalico"},
{"c":6,"l":"Hop test","t":"Non eseguibili in fase acuta.","k":1,"w":"Servono più avanti per la classificazione coper / non-coper e per il rientro, non in acuto.","s":"Fitzgerald 2000 (PMID 10795668)","a":"hop salto"},
{"c":7,"l":"Test di Lachman","t":"Traslazione anteriore aumentata a sinistra con fine corsa morbido. Destra con arresto netto.","k":1,"w":"È il test clinico di riferimento per l'integrità del LCA.","a":"lachman"},
{"c":7,"l":"Cassetto anteriore","t":"Aumentato a sinistra, poco valutabile per la difesa.","a":"anterior drawer"},
{"c":7,"l":"Lever test","t":"Positivo a sinistra: il tallone non si alza quando si spinge sul quadricipite.","k":1,"w":"Utile in acuto quando il paziente si difende.","a":"lever lelli"},
{"c":7,"l":"Pivot shift","t":"Non eseguibile: il paziente si difende.","a":"pivot shift"},
{"c":7,"l":"Stress in valgo a 0° e 30°","t":"A 0° stabile. A 30° lieve dolore mediale con apertura appena aumentata e arresto netto.","k":1,"w":"Valuta il collaterale mediale, spesso associato nelle lesioni del LCA.","a":"valgo collaterale mediale"},
{"c":7,"l":"Stress in varo","t":"Negativo.","a":"varo"},
{"c":7,"l":"Cassetto posteriore e sag sign","t":"Negativi.","a":"lcp posteriore"},
{"c":7,"l":"Test meniscali (McMurray, Thessaly)","t":"Non eseguibili per dolore e versamento. Nessun blocco riferito.","a":"mcmurray thessaly menisco"},
{"c":8,"l":"RX del ginocchio","t":"Nessuna frattura, nessun distacco osseo laterale della tibia.","a":"radiografia segond"},
{"c":8,"l":"Risonanza magnetica","t":"Rottura completa del LCA. Contusione ossea al condilo femorale laterale e al piatto tibiale postero-laterale. Collaterale mediale con lesione di I grado. Menischi e cartilagine integri.","k":1,"w":"Conferma la diagnosi e cerca lesioni associate (menisco, collaterali, cartilagine) che cambiano il percorso.","a":"rm rmn"}
]},
{"id":"coscia-sprint","d":"Muscoli","t":"Ala, 20 anni, coscia posteriore durante uno sprint","chips":["20 anni","Ala (14)","Serie A2","1,78 m · 80 kg","Coscia destra"],"testo":"Andrea è un'ala di serie A2. Domenica, a dieci minuti dalla fine, stava sprintando su un pallone calciato in avanti quando ha sentito una fitta dietro la coscia destra. Si è fermato subito ed è uscito camminando. Oggi è martedì e viene da te camminando con un passo più corto a destra.","diag":"Lesione acuta tipo sprint del capo lungo del bicipite femorale destro, giunzione muscolo-tendinea, tendine intramuscolare integro. Lombare e nervo sciatico esclusi come fonte del dolore.","schede":[["hamstring-acuta","Lesione acuta degli hamstring"]],items:[
{"c":0,"l":"Meccanismo","t":"«Stavo correndo al massimo, nella fase in cui la gamba si allunga davanti per appoggiare. Fitta improvvisa dietro la coscia, come una pugnalata.»","k":1,"w":"Lesione durante lo sprint a alta velocità: tipo sprint, di solito il capo lungo del bicipite, con rientro più breve del tipo da allungamento.","s":"Martin 2022 (PMID 35164536)","a":"come dinamica sprint"},
{"c":0,"l":"Momento della partita e fatica","t":"«Ultimi dieci minuti, ero stanco.»","a":"fatica"},
{"c":0,"l":"Dolore e capacità di continuare","t":"«Mi sono fermato subito, non potevo più correre. Al momento 7/10, ora 2/10 a riposo e 4/10 se cammino veloce.»","k":1,"w":"Dolore alto e impossibilità di continuare sono segni di gravità da combinare con l'esame.","a":"vas nrs"},
{"c":0,"l":"Lesioni precedenti","t":"«L'anno scorso uno stiramento alla stessa coscia, sono stato fermo tre settimane. Ho fatto la riabilitazione, ma l'eccentrico l'ho smesso quando ho ripreso a giocare.»","k":1,"w":"Una lesione precedente è il principale fattore di rischio di nuova lesione.","s":"Green 2020 (DOI 10.1136/bjsports-2019-100983)","a":"storia pregressa recidiva"},
{"c":0,"l":"Mal di schiena o sintomi alla gamba","t":"«Nessun mal di schiena, niente formicolii.»","k":1,"w":"Esclude un dolore riferito dalla colonna o dal nervo sciatico.","a":"lombare formicolio"},
{"c":0,"l":"Prevenzione abituale","t":"«In squadra il Nordic lo facciamo ogni tanto, non tutte le settimane.»","a":"nordic prevenzione"},
{"c":1,"l":"Ispezione della coscia","t":"Piccola ecchimosi nella parte posterolaterale della coscia, a metà. Nessuna deformità o avvallamento.","a":"ecchimosi livido"},
{"c":1,"l":"Cammino","t":"Passo più corto a destra, ginocchio meno esteso a fine oscillazione.","a":"andatura"},
{"c":2,"l":"Sensibilità di coscia e gamba","t":"Normale e simmetrica.","a":"neurologico"},
{"c":2,"l":"Riflessi","t":"Achilleo e rotuleo presenti e simmetrici.","a":"riflessi"},
{"c":3,"l":"Palpazione e sede del punto più doloroso","t":"Punto più doloroso sul bicipite femorale, nella parte laterale della coscia, a circa 12 cm dalla tuberosità ischiatica.","k":1,"w":"La sede del dolore indica il muscolo e la zona coinvolta e orienta la prognosi.","s":"Martin 2022 (PMID 35164536)","a":"palpazione tuberosità"},
{"c":3,"l":"Lunghezza della zona dolente","t":"Circa 8 cm.","k":1,"w":"È una misura clinica usata per stimare l'estensione della lesione e seguirne il recupero.","s":"Martin 2022 (PMID 35164536)","a":"estensione lunghezza"},
{"c":3,"l":"Palpazione della tuberosità ischiatica","t":"Non dolente, nessun distacco palpabile.","k":1,"w":"Esclude il coinvolgimento del tendine prossimale e l'avulsione, che hanno un percorso diverso.","a":"avulsione ischio"},
{"c":4,"l":"Active knee extension (AKE)","t":"Destra mancano 35° all'estensione completa, con dolore. Sinistra mancano 15°.","k":1,"w":"Il deficit tra i lati è legato ai tempi di rientro e guida la progressione della corsa.","s":"Martin 2022 (PMID 35164536)","a":"ake"},
{"c":4,"l":"Sollevamento passivo a gamba tesa","t":"Destra 55° con dolore alla coscia, sinistra 85°.","a":"slr passivo"},
{"c":5,"l":"Flessione di ginocchio resistita da prono","t":"A 90° forte e lievemente dolorosa. A 15° dolore 5/10 e forza ridotta.","k":1,"w":"Dolore e forza persa in posizione più allungata indicano tessuto ancora irritabile.","s":"Hickey 2022 (DOI 10.4085/1062-6050-0707.20)","a":"contrazione resistita forza"},
{"c":5,"l":"Forza isometrica al dinamometro","t":"Ginocchio a 90°: destra 82% della sinistra. Ginocchio a 30°: non eseguibile per dolore.","k":1,"w":"La forza a più angoli dà il deficit specifico per lunghezza muscolare.","s":"Martin 2022 (PMID 35164536)","a":"hhd dinamometro"},
{"c":5,"l":"Ponte monopodalico","t":"Destra non tollerato, sinistra 25 ripetizioni.","a":"single leg bridge"},
{"c":5,"l":"Forza dei glutei e del polpaccio","t":"Conservata.","a":"glutei polpaccio"},
{"c":6,"l":"Corsa e sprint","t":"Non eseguibili oggi.","a":"corsa sprint"},
{"c":6,"l":"Controllo lombo-pelvico","t":"In appoggio monopodalico a destra lieve caduta del bacino.","a":"controllo bacino"},
{"c":7,"l":"Slump test","t":"Negativo: nessun sintomo neurale.","k":1,"w":"Esclude una componente neurale che cambierebbe trattamento e prognosi.","a":"slump neurodinamico"},
{"c":7,"l":"Askling H-test","t":"Non eseguibile in acuto.","k":1,"w":"Valuta l'apprensione residua: è un test per il rientro, non per la fase acuta.","s":"Askling 2010 (DOI 10.1007/s00167-010-1265-3)","a":"h test apprensione"},
{"c":7,"l":"Test lombari e sacroiliaci","t":"Negativi.","a":"lombare sacroiliaca"},
{"c":8,"l":"Ecografia","t":"Area di alterazione alla giunzione muscolo-tendinea del capo lungo del bicipite femorale.","a":"ecografia"},
{"c":8,"l":"Risonanza magnetica","t":"Lesione alla giunzione muscolo-tendinea del capo lungo del bicipite femorale destro, estesa 7 cm. Tendine intramuscolare integro, tendine prossimale integro.","k":1,"w":"Aiuta la prognosi (coinvolgimento del tendine, estensione), ma aggiunge poco all'esame clinico per decidere il trattamento.","s":"Martin 2022 (PMID 35164536)","a":"rm rmn"}
]},
{"id":"spalla-placcaggio","d":"Spalla","t":"Seconda linea, 23 anni, spalla dopo un placcaggio","chips":["23 anni","Seconda linea (4)","Serie A2","1,96 m · 112 kg","Spalla destra (dominante)"],"testo":"Davide è una seconda linea di serie A2. Dieci giorni fa ha placcato un avversario con il braccio destro aperto e portato indietro. La spalla è «uscita»: è stata rimessa a posto in pronto soccorso e ha portato il tutore per una settimana. È il primo episodio. Viene da te con il braccio libero, ma lo tiene vicino al corpo.","diag":"Prima lussazione anteriore traumatica di spalla destra, con lesione di Bankart e piccola lesione di Hill-Sachs; nervo ascellare integro. Alto rischio di recidiva (giovane, maschio, sport di contatto): percorso conservativo con decisione chirurgica da discutere con l'ortopedico.","schede":[["spalla-instab-ant","Instabilità anteriore di spalla"]],items:[
{"c":0,"l":"Meccanismo","t":"«Ho placcato con il braccio aperto, alto, e l'avversario me l'ha spinto indietro. Ho sentito la spalla uscire davanti.»","k":1,"w":"Abduzione ed extrarotazione forzate: meccanismo tipico della lussazione anteriore.","a":"come dinamica placcaggio"},
{"c":0,"l":"Riduzione e trattamento in pronto soccorso","t":"«L'hanno rimessa a posto in pronto soccorso dopo le radiografie. Tutore per sette giorni.»","a":"riduzione tutore"},
{"c":0,"l":"Episodi precedenti","t":"«Mai successo prima, né a destra né a sinistra.»","k":1,"w":"Numero di episodi, età e sport di contatto sono i principali fattori di recidiva.","s":"Olds 2015, revisione sistematica (nella scheda, PMID non ancora verificato)","a":"recidiva primo episodio"},
{"c":0,"l":"Lassità generale","t":"«Non sono mai stato snodato.»","a":"lassità"},
{"c":0,"l":"Dolore e sensazione di instabilità","t":"«A riposo 2/10. Se alzo il braccio di lato e lo porto indietro ho paura che esca.»","a":"vas apprensione"},
{"c":0,"l":"Formicolii o debolezza al braccio","t":"«Nei primi giorni un po' di intorpidimento sulla spalla, ora passato.»","k":1,"w":"Va sempre chiesto: il nervo ascellare può essere lesionato nella lussazione.","a":"formicolio nervo ascellare"},
{"c":0,"l":"Lato dominante e ruolo","t":"«Sono destro. In seconda linea placco tanto, salgo in touche e spingo in mischia.»","a":"dominanza ruolo touche"},
{"c":1,"l":"Ispezione della spalla","t":"Profilo del deltoide simmetrico, nessuna ecchimosi residua importante, scapola lievemente più bassa e in avanti a destra.","a":"deltoide scapola"},
{"c":1,"l":"Ispezione del rachide cervicale","t":"Nessun reperto significativo.","a":"cervicale"},
{"c":2,"l":"Sensibilità sul deltoide laterale","t":"Normale e simmetrica.","k":1,"w":"È il territorio del nervo ascellare: va controllato dopo ogni lussazione.","a":"nervo ascellare badge"},
{"c":2,"l":"Sensibilità di braccio e mano","t":"Normale.","a":"neurologico"},
{"c":2,"l":"Contrazione del deltoide","t":"Presente e visibile.","k":1,"w":"Completa la valutazione del nervo ascellare.","a":"deltoide contrazione ascellare"},
{"c":3,"l":"Palpazione della spalla","t":"Lieve dolore anteriore sulla capsula e sul tubercolo minore; acromion-claveare e grande tubercolo non dolenti.","a":"palpazione"},
{"c":4,"l":"Mobilità attiva e passiva","t":"Flessione attiva destra 150°, sinistra 175°. Abduzione destra 130° con apprensione. Extrarotazione a braccio lungo il corpo 50° (sinistra 75°). Extrarotazione a 90° di abduzione non testata per apprensione.","a":"rom"},
{"c":4,"l":"Rotazione interna","t":"Mano dietro la schiena fino a L1 a destra, T8 a sinistra.","a":"intrarotazione"},
{"c":5,"l":"Forza dei rotatori al dinamometro","t":"Extrarotazione: destra 72% della sinistra. Intrarotazione: 85%. Lieve dolore all'extrarotazione.","k":1,"w":"Valore di partenza da confrontare con il lato sano e con valori assoluti; è anche criterio di rientro.","a":"hhd dinamometro rotatori"},
{"c":5,"l":"Forza del sottoscapolare (belly press, lift-off)","t":"Belly press negativo, lift-off non eseguibile per dolore.","a":"sottoscapolare"},
{"c":5,"l":"Forza dei muscoli scapolari","t":"Trapezio inferiore e dentato anteriore ridotti a destra.","a":"scapola dentato"},
{"c":6,"l":"Funzione in appoggio (CKCUEST)","t":"Non eseguito oggi.","a":"ckcuest catena chiusa"},
{"c":6,"l":"Questionario di funzione della spalla","t":"Limitazioni sopra la testa e nello sport.","a":"questionario wosi"},
{"c":7,"l":"Test di apprensione","t":"Positivo: apprensione a 90° di abduzione e 60° di extrarotazione.","k":1,"w":"L'apprensione, più del solo dolore, indica instabilità anteriore.","a":"apprensione"},
{"c":7,"l":"Test di rilocazione","t":"Positivo: l'apprensione si riduce con la spinta posteriore sulla testa omerale.","k":1,"w":"La riduzione dell'apprensione con la rilocazione rafforza il sospetto di instabilità anteriore.","a":"rilocazione relocation"},
{"c":7,"l":"Sulcus sign e punteggio di Beighton","t":"Sulcus negativo. Beighton 2/9.","k":1,"w":"La lassità generale è un fattore di recidiva nei giovani.","a":"sulcus beighton lassità"},
{"c":7,"l":"Load and shift","t":"Traslazione anteriore di grado 1 a destra, dolorosa; sinistra grado 1 indolore.","a":"load shift"},
{"c":7,"l":"Test per la cuffia e per il bicipite","t":"Negativi.","a":"cuffia bicipite"},
{"c":8,"l":"RX dopo la riduzione","t":"Testa omerale ridotta. Piccola lesione di Hill-Sachs. Nessuna frattura della glena.","a":"radiografia"},
{"c":8,"l":"Risonanza magnetica con contrasto","t":"Lesione di Bankart del labbro antero-inferiore. Hill-Sachs piccola. Perdita ossea della glena non significativa. Cuffia integra.","k":1,"w":"Labbro, perdita ossea e cuffia cambiano la scelta tra conservativo e chirurgia.","a":"rm artro"}
]},
{"id":"caviglia-sidestep","d":"Caviglia","t":"Mediano di mischia, 22 anni, caviglia in un cambio di direzione","chips":["22 anni","Mediano di mischia (9)","Serie A2","1,74 m · 76 kg","Caviglia sinistra"],"testo":"Tommaso è il mediano di mischia titolare di una squadra di serie A2. Sabato, su un campo pesante per la pioggia, ha fatto un sidestep sul piede sinistro per evitare un avversario: il piede è scivolato ed è andato in dentro sotto il peso del corpo. È rimasto a terra qualche secondo, poi è uscito camminando da solo, zoppicando. Non è la prima volta che si fa male a quella caviglia. Oggi è mercoledì, quattro giorni dopo il trauma, e viene da te camminando con una leggera zoppia.","diag":"Distorsione laterale di caviglia sinistra di II grado (lesione parziale del legamento peroneo-astragalico anteriore, peroneo-calcaneare sollecitato ma continente), recidiva su quadro di instabilità cronica di caviglia (terzo episodio, giving way ricorrente, CAIT 17/30). Regole di Ottawa negative: radiografia non indicata; sindesmosi, avulsione della base del V metatarso e frattura di Maisonneuve escluse clinicamente. Deficit di forza degli eversori, di dorsiflessione in carico e di equilibrio monopodalico.","schede":[["caviglia-laterale","Distorsione laterale di caviglia e instabilità cronica"]],"items":[{"c":0,"l":"Meccanismo del trauma","t":"«Ho fatto un sidestep sul sinistro per saltare l'uomo, il campo era bagnato e il piede è scivolato. La punta era giù e il piede si è girato verso l'interno, con tutto il peso sopra. È successo in un attimo.»","k":1,"w":"Flessione plantare forzata con supinazione in carico è il meccanismo tipico della distorsione laterale: orienta verso il peroneo-astragalico anteriore prima ancora dei test.","a":"dinamica inversione supinazione come ti sei fatto male"},{"c":0,"l":"Cosa è stato avvertito al momento","t":"«Un dolore forte sul lato esterno, 7/10, come qualcosa che tirava e poi si strappava. Nessuno schiocco forte. Non ho sentito male sopra la caviglia né dentro.»","a":"schiocco strappo dolore iniziale"},{"c":0,"l":"Capacità di camminare dopo il trauma","t":"«Dopo qualche secondo mi sono rialzato e sono uscito da solo, zoppicando, senza che nessuno mi reggesse. Ho fatto i 30 metri fino alla panchina.»","k":1,"w":"La capacità di fare almeno 4 passi subito dopo il trauma e alla visita è uno dei criteri delle regole di Ottawa.","s":"Vuurberg 2018 (PMID 29514819)","a":"ottawa passi appoggio carico"},{"c":0,"l":"Sede del dolore","t":"«Sul lato esterno, davanti e sotto l'osso sporgente. Non sopra la caviglia, non sul dorso del piede.»","a":"dove localizzazione laterale"},{"c":0,"l":"Andamento da sabato","t":"«Sabato sera 6/10 e la caviglia era gonfia come un pallone. Oggi a riposo 1/10, camminando 3/10, in discesa e sulle superfici sconnesse 4-5/10.»","a":"miglioramento nrs vas edema"},{"c":0,"l":"Distorsioni precedenti","t":"«È la terza volta sulla stessa caviglia. La prima a 17 anni nelle giovanili, la seconda un anno e mezzo fa: ghiaccio, una cavigliera e dopo dieci giorni giocavo. Non ho mai fatto fisioterapia.»","k":1,"w":"Le recidive sono frequenti e una parte dei pazienti mantiene sintomi residui: distorsioni ripetute non riabilitate fanno pensare a un'instabilità cronica, che cambia obiettivi e prevenzione.","s":"van Rijn 2008 (PMID 18374692); Gribble 2016 (PMID 27259750)","a":"storia pregressa recidiva"},{"c":0,"l":"Sensazione di cedimento","t":"«Anche prima di sabato, sui campi sconnessi o scendendo dal marciapiede, ogni tanto la caviglia mi cede: due o tre volte al mese. Non fa sempre male, ma mi spavento.»","k":1,"w":"Episodi ripetuti di cedimento (giving way) sono uno dei criteri dell'International Ankle Consortium per l'instabilità cronica.","s":"Gribble 2014 (PMID 23902805)","a":"giving cedimento instabilità"},{"c":0,"l":"Cosa è stato fatto finora","t":"«Ghiaccio e piede in alto il primo giorno, poi ho camminato come riuscivo. Nessun esame, nessun tutore. Il preparatore mi ha messo un bendaggio per due giorni.»","a":"trattamenti precedenti bendaggio"},{"c":0,"l":"Ruolo e carichi","t":"«Faccio il mediano di mischia: tanti cambi di direzione, partenze brevi, passaggi dal raggruppamento. Quattro allenamenti a settimana più la partita.»","a":"allenamento partita ruolo"},{"c":1,"l":"Ispezione della caviglia","t":"Edema moderato perimalleolare laterale a sinistra, più marcato davanti e sotto il malleolo peroneale. Ecchimosi violacea sotto il malleolo laterale che scende verso il margine esterno del piede. Nessuna ecchimosi mediale né sopra la rima. Nessuna deformità, pelle integra.","a":"edema ecchimosi gonfiore ematoma"},{"c":1,"l":"Misurazione del gonfiore (figura a 8)","t":"Sinistra 53,5 cm, destra 51,5 cm. Differenza 2 cm.","a":"circonferenza misura edema"},{"c":2,"l":"Sensibilità del piede","t":"Tatto e dolore normali e simmetrici sul dorso, sul margine laterale (surale) e sulla pianta, anche nel territorio del peroneo superficiale.","a":"neurologico surale peroneo"},{"c":2,"l":"Polsi pedidio e tibiale posteriore","t":"Presenti e simmetrici. Riempimento capillare normale.","a":"vascolare circolo polsi"},{"c":3,"l":"Palpazione dei malleoli (bordo posteriore e punta, ultimi 6 cm)","t":"Malleolo laterale e malleolo mediale: non dolenti sul bordo posteriore e sulla punta. Dolore solo davanti e sotto il malleolo laterale, sui tessuti molli.","k":1,"w":"Fa parte delle regole di Ottawa: dolore osseo ai malleoli indica la radiografia per escludere una frattura.","s":"Vuurberg 2018 (PMID 29514819)","a":"ottawa malleolo ossa"},{"c":3,"l":"Palpazione della base del V metatarso e del navicolare","t":"Base del V metatarso: non dolente. Navicolare: non dolente.","k":1,"w":"Completa le regole di Ottawa per il piede; la base del V metatarso va sempre palpata per l'avulsione da peroneo breve.","s":"Vuurberg 2018 (PMID 29514819)","a":"ottawa metatarso navicolare avulsione"},{"c":3,"l":"Palpazione della testa e della diafisi del perone","t":"Testa e diafisi prossimale del perone non dolenti.","k":1,"w":"Esclude la frattura di Maisonneuve (lesione della membrana interossea con frattura prossimale del perone).","a":"maisonneuve testa perone"},{"c":3,"l":"Palpazione del legamento peroneo-astragalico anteriore","t":"Dolore marcato, 6/10, riproduce il suo dolore: «è proprio lì».","a":"atfl peroneo astragalico"},{"c":3,"l":"Palpazione del legamento peroneo-calcaneare","t":"Dolore lieve, 3/10, sotto la punta del malleolo.","a":"cfl calcaneare"},{"c":3,"l":"Palpazione del legamento deltoideo e della sindesmosi anteriore","t":"Deltoideo non dolente. Legamento tibio-peroneale anteriore non dolente, nessun dolore sopra la rima.","a":"deltoideo sindesmosi mediale"},{"c":3,"l":"Palpazione dei tendini peronei","t":"Tendini peronei dietro il malleolo laterale non dolenti, nessuna sublussazione all'eversione contro resistenza.","a":"peronei tendinopatia"},{"c":4,"l":"Escursioni attive e passive della caviglia","t":"Dorsiflessione passiva a ginocchio esteso sinistra 8°, destra 15°; a ginocchio flesso sinistra 14°, destra 24°, con fastidio anteriore e laterale a fine corsa. Flessione plantare sinistra 38° con dolore laterale, destra 48°. Inversione sinistra 20° dolorosa, destra 30°. Eversione simmetrica e indolore.","a":"rom goniometro dorsiflessione"},{"c":5,"l":"Eversione con dinamometro manuale","t":"Sinistra 11 kg con dolore laterale 3/10, destra 17 kg. Deficit circa 35%.","k":1,"w":"La forza dei peronei è uno dei bersagli principali e un criterio di rientro (forza almeno 90-95% del lato sano, soglia operativa).","a":"dinamometro peronei eversori hhd"},{"c":5,"l":"Inversione e flessione plantare con dinamometro manuale","t":"Inversione sinistra 14 kg con dolore laterale, destra 18 kg. Flessione plantare sinistra 24 kg, destra 30 kg.","a":"dinamometro tibiale posteriore"},{"c":5,"l":"Calf raise monopodalico fino a fatica","t":"Sinistra 12 ripetizioni con fastidio laterale e tallone che ruota verso l'esterno nelle ultime; destra 28.","a":"heel raise polpaccio tricipite"},{"c":6,"l":"Cammino","t":"Lieve zoppia a sinistra: appoggio accorciato, spinta dell'avampiede ridotta, piede un po' extraruotato. Nessun ausilio. Dolore 3/10.","a":"deambulazione andatura gait"},{"c":6,"l":"Dorsiflessione in carico (lunge al muro)","t":"Sinistra 6 cm con tensione anteriore, destra 11 cm.","k":1,"w":"Il lunge in carico è la misura di riferimento della dorsiflessione funzionale e va ripetuto nel follow-up fino alla simmetria.","a":"wblt weight bearing lunge"},{"c":6,"l":"Appoggio monopodalico","t":"Occhi aperti: sinistra 15 secondi con molte correzioni di caviglia, destra 30 secondi stabile. Occhi chiusi: sinistra 3 secondi, destra 14.","k":1,"w":"Il controllo neuromuscolare è il fattore più modificabile per ridurre le recidive: è un bersaglio delle fasi e un criterio di rientro.","a":"equilibrio monopodalico propriocezione"},{"c":6,"l":"Questionario CAIT","t":"Sinistra 17/30, destra 28/30.","k":1,"w":"Il CAIT quantifica l'instabilità percepita e fa parte dei criteri di selezione dell'International Ankle Consortium per l'instabilità cronica.","s":"Gribble 2014 (PMID 23902805)","a":"cumberland questionario instabilità"},{"c":6,"l":"Y-balance, hop e corsa","t":"Non eseguiti oggi: dolore e apprensione in carico monopodalico dinamico.","a":"y balance salto corsa"},{"c":7,"l":"Cassetto anteriore","t":"Traslazione anteriore dell'astragalo aumentata a sinistra rispetto a destra, arresto morbido, dolore laterale. Eseguito a 4 giorni dal trauma.","k":1,"w":"Valuta la lassità del peroneo-astragalico anteriore; eseguito a 4-5 giorni dal trauma, quando dolore ed edema sono minori, è più attendibile.","s":"Vuurberg 2018 (PMID 29514819)","a":"anterior drawer cassetto"},{"c":7,"l":"Talar tilt","t":"Inclinazione in inversione lievemente aumentata a sinistra, con arresto presente e dolore sotto il malleolo.","k":1,"w":"Valuta il peroneo-calcaneare: lassità lieve con arresto presente è compatibile con una lesione parziale, non completa.","a":"inversione stress tilt"},{"c":7,"l":"Squeeze test e stress in rotazione esterna","t":"Entrambi negativi: nessun dolore sopra la rima.","k":1,"w":"Se negativi escludono una lesione della sindesmosi, che è una red flag e cambierebbe tempi e percorso.","a":"squeeze sindesmosi rotazione esterna kleiger"},{"c":7,"l":"Test di Thompson","t":"Negativo.","a":"achille rottura"},{"c":8,"l":"Radiografia","t":"Non richiesta: regole di Ottawa negative.","k":1,"w":"Le regole di Ottawa indicano quando serve la radiografia: se tutte negative, l'imaging non è necessario.","s":"Vuurberg 2018 (PMID 29514819)","a":"radiografia rx imaging"},{"c":8,"l":"Ecografia (eseguita dal medico della società)","t":"Legamento peroneo-astragalico anteriore ispessito con discontinuità parziale delle fibre. Peroneo-calcaneare ispessito ma continuo. Modesto versamento articolare. Tendini peronei regolari.","a":"ecografia ultrasuoni"}]},
{"id":"tallone-pilone","d":"Caviglia","t":"Pilone, 33 anni, dolore dietro la caviglia in preparazione","chips":["33 anni","Pilone destro (3)","Serie A2","1,82 m · 118 kg","Tendine d'Achille destro"],"testo":"Davide è un pilone destro di serie A2. Da circa sei settimane ha dolore dietro la caviglia destra. È iniziato piano piano durante la preparazione estiva, quando lo staff ha aumentato la corsa: ripetute e lavoro a navetta su campi duri e secchi. Non ricorda un trauma. Continua ad allenarsi, ma la mattina fatica a fare i primi passi e il dolore dopo le sedute di corsa sta aumentando. Il campionato inizia tra quattro settimane.","diag":"Tendinopatia achillea del tratto medio destro, a esordio graduale dopo un aumento del carico di corsa in preparazione. Rottura (Thompson negativo, nessun evento acuto) e trombosi venosa profonda escluse; nessun segno di tendinopatia inserzionale o di borsite retrocalcaneare. Ispessimento fusiforme a 4 cm dall'inserzione, deficit di capacità di carico del polpaccio (heel raise 14 contro 25), VISA-A 58/100.","schede":[["achille-medio","Tendinopatia achillea del tratto medio"]],"items":[{"c":0,"l":"Esordio e carico","t":"«Nessun trauma. È iniziato in preparazione, alla seconda settimana, quando abbiamo aggiunto le ripetute e le navette due volte a settimana. Prima correvo poco, il mio lavoro è in mischia.»","k":1,"w":"Esordio graduale legato a un aumento rapido della corsa è il quadro tipico: indica quale carico va gestito, senza riposo totale.","a":"inizio carico preparazione corsa"},{"c":0,"l":"Sede del dolore","t":"«Dietro la caviglia, sul tendine, più o meno tre dita sopra il tallone. Sul tallone vero e proprio non mi fa male.»","k":1,"w":"Un dolore localizzato circa 2-6 cm sopra l'inserzione indica il tratto medio e lo distingue dalla tendinopatia inserzionale.","a":"dove localizzazione tendine"},{"c":0,"l":"Rigidità al mattino","t":"«La mattina i primi passi sono duri, cammino come un pinguino per 15-20 minuti, poi si scioglie.»","a":"mattina rigidità primi passi"},{"c":0,"l":"Andamento durante e dopo la corsa","t":"«All'inizio della seduta fa male 4/10, poi si scalda e quasi sparisce. Il problema è dopo, la sera e la mattina seguente: arrivo a 5/10.»","k":1,"w":"Il dolore e la rigidità nelle 24 ore successive al carico sono il riferimento per dosare la progressione e per il rientro.","s":"Silbernagel 2015 (PMID 26390272)","a":"giorno dopo 24 ore risposta riscaldamento"},{"c":0,"l":"Evento acuto, schiocco o colpo","t":"«No, mai sentito un colpo o uno schiocco. Non mi è mai mancata la forza di spingere.»","k":1,"w":"Un colpo improvviso con debolezza fa sospettare una rottura, che è una red flag e richiede valutazione urgente.","a":"rottura schiocco colpo"},{"c":0,"l":"Gonfiore e calore al polpaccio","t":"«No, il polpaccio è normale. Solo il tendine sembra un po' più grosso dell'altro.»","k":1,"w":"Polpaccio gonfio, caldo e dolente richiede di escludere una trombosi venosa profonda.","a":"tvp trombosi polpaccio"},{"c":0,"l":"Dolore notturno e sintomi generali","t":"«Di notte dormo bene. Niente febbre, niente dolori in altre articolazioni.»","a":"notte febbre sistemici"},{"c":0,"l":"Farmaci e proposte di infiltrazione","t":"«Prendo un antinfiammatorio dopo le sedute più dure. Nessun antibiotico negli ultimi mesi. Un compagno mi ha detto di farmi fare un'infiltrazione di cortisone per arrivare pronto al campionato.»","k":1,"w":"Le infiltrazioni di corticosteroidi vanno evitate come strategia di recupero per il rischio di indebolire il tendine.","a":"infiltrazione cortisone farmaci fans"},{"c":0,"l":"Infortuni precedenti","t":"«Due anni fa un po' di fastidio allo stesso tendine a fine stagione, passato da solo in due settimane. Nessun altro problema a caviglia e polpaccio.»","a":"storia pregressa"},{"c":0,"l":"Superfici, scarpe e calendario","t":"«Le ripetute le facciamo sul campo secondario, duro come cemento in agosto. Ho cambiato da poco le scarpe da corsa. Il campionato parte tra quattro settimane.»","a":"terreno calzature scarpe campionato"},{"c":1,"l":"Ispezione in prono","t":"Ispessimento fusiforme del tendine d'Achille destro circa 4 cm sopra l'inserzione, visibile in confronto con il sinistro. Nessun gap, nessun arrossamento. Profilo del calcagno regolare, nessuna prominenza posteriore.","a":"ispessimento nodulo tendine"},{"c":1,"l":"Ispezione del polpaccio","t":"Polpacci simmetrici, morbidi, non caldi né arrossati. Circonferenza massima destra 41 cm, sinistra 41,5 cm.","a":"trofismo polpaccio circonferenza"},{"c":2,"l":"Sensibilità del piede e del territorio surale","t":"Normale e simmetrica, anche sul margine laterale del piede.","a":"neurologico surale"},{"c":2,"l":"Riflesso achilleo","t":"Presente e simmetrico.","a":"riflesso achilleo"},{"c":3,"l":"Palpazione del tratto medio","t":"Dolore riconoscibile 3-5 cm sopra l'inserzione, 5/10, con ispessimento palpabile: «è quello».","k":1,"w":"La dolorabilità localizzata nel tratto medio sostiene l'origine tendinea del dolore.","s":"Martin 2018 (PMID 29712543)","a":"palpazione tendine tratto medio"},{"c":3,"l":"Palpazione dell'inserzione e della borsa retrocalcaneare","t":"Inserzione sul calcagno non dolente. Compressione ai lati del tendine sopra il calcagno non dolente.","k":1,"w":"Serve a distinguere la tendinopatia del tratto medio da quella inserzionale e dalla borsite retrocalcaneare, che si gestiscono in modo diverso.","a":"inserzionale borsa calcagno haglund"},{"c":3,"l":"Palpazione del ventre del polpaccio","t":"Gastrocnemio e soleo non dolenti, nessun punto di tensione rilevante.","a":"gastrocnemio soleo muscolo"},{"c":4,"l":"Dorsiflessione passiva (goniometro)","t":"Ginocchio esteso: destra 10°, sinistra 13°. Ginocchio flesso: destra 18°, sinistra 22°. Lieve tensione posteriore a destra a fine corsa.","a":"rom goniometro dorsiflessione"},{"c":4,"l":"Flessione plantare e mobilità sottoastragalica","t":"Flessione plantare simmetrica (45° e 46°). Inversione ed eversione simmetriche e indolori.","a":"plantare sottoastragalica"},{"c":5,"l":"Heel raise monopodalico standardizzato","t":"Ritmo fisso con metronomo, altezza massima del tallone: destra 14 ripetizioni, fermato da dolore 5/10 e perdita di altezza; sinistra 25 ripetizioni.","k":1,"w":"Misura la capacità di carico del polpaccio: è il valore di partenza della fase di forza e un criterio di rientro.","a":"heel raise calf raise polpaccio"},{"c":5,"l":"Flessione plantare con dinamometro manuale","t":"Destra 32 kg con dolore 3/10, sinistra 39 kg. Deficit circa 18%.","k":1,"w":"La forza del polpaccio protegge il tendine; il criterio di rientro operativo è almeno 90-95% del lato sano.","a":"dinamometro plantiflessori hhd"},{"c":5,"l":"Calf raise seduto (soleo)","t":"Con 20 kg sulle ginocchia: destra 15 ripetizioni con fastidio, sinistra 22.","a":"soleo seduto"},{"c":6,"l":"Questionario VISA-A","t":"58/100 a destra.","k":1,"w":"Quantifica dolore, funzione e sport ed è utile per il follow-up; da solo non decide il rientro.","s":"Martin 2018 (PMID 29712543)","a":"visa questionario"},{"c":6,"l":"Pogo bipodalico e hop monopodalico","t":"Pogo bipodalico 20 contatti: dolore 3/10. Hop monopodalico destro: dolore 5/10 dopo 8 salti, contatti lunghi e rumorosi; sinistro 20 salti senza dolore.","a":"pogo salto hop pliometria"},{"c":6,"l":"Cammino e squat","t":"Cammino normale. Squat bipodalico completo indolore. Discesa delle scale con fastidio lieve.","a":"deambulazione squat scale"},{"c":7,"l":"Arc sign","t":"Positivo: l'ispessimento dolente si sposta con il tendine durante la flessione plantare e dorsale attiva.","k":1,"w":"Indica che il dolore e l'ispessimento sono nel tendine e non nel paratenonio.","s":"Martin 2018 (PMID 29712543)","a":"arc arco paratenonite"},{"c":7,"l":"Royal London Hospital test","t":"Positivo: dolore 5/10 a piede neutro, 1/10 nella stessa sede in dorsiflessione.","k":1,"w":"Il dolore che diminuisce in dorsiflessione suggerisce una tendinopatia.","s":"Martin 2018 (PMID 29712543)","a":"royal london"},{"c":7,"l":"Test di Thompson","t":"Negativo: flessione plantare presente e simmetrica alla compressione del polpaccio.","k":1,"w":"Esclude la rottura del tendine d'Achille, red flag che richiede valutazione urgente.","a":"thompson simmonds rottura"},{"c":8,"l":"Ecografia","t":"Ispessimento fusiforme del tratto medio (8,5 mm contro 5,5 mm), aree ipoecogene, neovascolarizzazione al power doppler. Inserzione e borsa retrocalcaneare regolari, nessuna lesione parziale.","k":1,"w":"L'imaging non è sempre necessario per la diagnosi: qui conferma il quadro ed esclude una lesione parziale, ma non decide da solo il carico.","a":"ecografia ultrasuoni doppler"},{"c":8,"l":"Risonanza magnetica","t":"Non eseguita: non necessaria.","a":"risonanza rmn"}]},
{"id":"testa-placcaggio","d":"Testa","t":"Centro, 24 anni, il giorno dopo un placcaggio","chips":["24 anni","Centro (12)","Serie A2","1,84 m · 92 kg","Testa e collo"],"testo":"Andrea è un primo centro di serie A2. Sabato, a metà del secondo tempo, ha placcato un avversario che entrava in corsa da sinistra, ma ha messo la testa davanti al portatore invece che dietro: l'anca dell'avversario lo ha colpito sulla tempia sinistra e il collo è stato piegato di lato. È rimasto a terra qualche secondo, si è rialzato e ha giocato ancora alcuni minuti, finché un compagno ha chiamato lo staff perché chiedeva più volte lo schema. Il medico della società lo ha visitato a fine partita e lo ha mandato a casa accompagnato, con l'indicazione di andare in pronto soccorso se peggiorava. Oggi è domenica e il medico te lo manda per iniziare il percorso: entra con gli occhiali da sole.","diag":"Commozione cerebrale correlata allo sport da placcaggio con la testa dalla parte sbagliata: nessuna perdita di coscienza, amnesia breve dei minuti successivi, 7 minuti di gioco dopo il colpo. Carico di sintomi moderato, componente vestibolare e oculomotoria (sintomi provocati da riflesso vestibolo-oculare e saccadi, equilibrio in tandem alterato) e componente cervicale muscolare (dolorabilità suboccipitale e del trapezio sinistro, ROM e forza del collo ridotti). Lesioni gravi e del rachide cervicale escluse dal medico. La partita tra 8 giorni non è realistica: attività leggera, poi esercizio aerobico sotto la soglia dei sintomi, collo ed esercizi vestibolari, ritorno graduale secondo il protocollo di World Rugby e via libera medico al contatto.","schede":[["commozione-cerebrale-sport","Commozione cerebrale nello sport e ritorno graduale"]],"items":[{"c":0,"l":"Meccanismo del trauma","t":"«Ho placcato con la spalla destra un avversario che arrivava da sinistra, ma ho messo la testa davanti a lui invece che dietro. Mi ha preso la sua anca sulla tempia sinistra e il collo è andato di lato verso destra, di colpo.»","k":1,"w":"Il placcaggio è l'evento più frequente nelle commozioni del rugby e la testa davanti al portatore è l'errore tecnico da correggere prima del rientro. Lo stesso colpo ha caricato anche il collo.","s":"Cosgrave 2018 (PMID 30513491)","a":"dinamica placcaggio testa sbagliata"},{"c":0,"l":"Perdita di coscienza e memoria dell'evento","t":"«Svenuto non credo, i compagni dicono che mi sono rialzato subito. Però non ricordo i minuti dopo il placcaggio: mi hanno detto che chiedevo lo schema della touche due volte. Mi ricordo bene il primo tempo e il viaggio in pullman.»","k":1,"w":"La perdita di coscienza è un segno di allarme; l'amnesia dei minuti successivi e le domande ripetute sono segni tipici di commozione e vanno riferiti al medico.","a":"svenuto svenimento amnesia ricordi memoria coscienza"},{"c":0,"l":"Gioco dopo il colpo","t":"«Ho continuato a giocare per circa sette minuti, poi il fisio mi ha fatto uscire. Mi sentivo strano ma pensavo passasse.»","k":1,"w":"Continuare a giocare dopo il colpo si associa a un recupero più lungo: è un fattore prognostico da registrare.","s":"Putukian 2023 (PMID 37316183)","a":"rimasto in campo continuato giocare"},{"c":0,"l":"Sintomi da ieri e segni di peggioramento","t":"«Mal di testa sulla tempia e dietro gli occhi, ieri sera 6/10, oggi 4/10. Testa pesante, come nella nebbia, la luce mi dà fastidio. Ieri sera un po' di nausea, ma non ho vomitato. Non mi sono sentito sempre più assonnato o confuso, anzi stamattina va meglio di ieri. Mai vista doppia, niente convulsioni.»","k":1,"w":"Cefalea forte o in aumento, vomito ripetuto, sonnolenza o confusione crescenti, visione doppia e convulsioni impongono il pronto soccorso. Qui i sintomi sono in calo: si può procedere dentro il percorso deciso dal medico.","a":"cefalea nausea vomito fotofobia peggioramento allarme"},{"c":0,"l":"Collo e sintomi a braccia e gambe","t":"«Il collo è rigido sul lato sinistro, ma lo muovo. Nessun formicolio né debolezza alle braccia o alle gambe, né ieri né oggi.»","a":"cervicale formicolii debolezza braccia gambe"},{"c":0,"l":"Sonno","t":"«Mi sono addormentato tardi e mi sono svegliato tre volte. Stamattina ero stanco.»","a":"dormire insonnia stanchezza"},{"c":0,"l":"Cosa ha fatto da ieri","t":"«Oggi sono stato a letto al buio quasi tutto il giorno, come mi avevano detto da ragazzo. Però ieri sera sono stato due ore sul telefono a rivedere la partita.»","k":1,"w":"Il riposo rigoroso fino alla scomparsa dei sintomi non funziona: nei primi 2 giorni servono attività leggera e schermi ridotti, poi esercizio aerobico prescritto.","s":"Leddy 2023 (PMID 37316185)","a":"riposo schermi telefono attività leggera"},{"c":0,"l":"Commozioni precedenti","t":"«Una a 19 anni, in Under 20: fermo tre settimane. Nessun'altra.»","k":1,"w":"Commozioni ripetute o recuperi sempre più lunghi richiedono una rivalutazione medica e specialistica; la storia va riferita al medico che decide il rientro.","a":"precedenti storia pregressa"},{"c":0,"l":"Emicrania, altre malattie e farmaci","t":"«Mai sofferto di emicrania. Nessuna malattia. Ieri sera un paracetamolo.»","a":"emicrania farmaci paracetamolo"},{"c":0,"l":"Valori di base pre-stagionali","t":"«A luglio ci hanno fatto le domande, la lista di parole e le prove di equilibrio, e ci hanno misurato la forza del collo.» I valori sono nella cartella della società.","a":"baseline basale prestagionale inizio stagione"},{"c":0,"l":"Calendario","t":"«Sabato prossimo c'è la partita in casa, tra otto giorni.»","a":"partita calendario"},{"c":1,"l":"Aspetto generale","t":"Vigile, orientato nel tempo e nello spazio, risponde in modo corretto ma un po' lento. Tiene gli occhiali da sole anche in palestra.","a":"vigile orientato aspetto"},{"c":1,"l":"Testa e collo","t":"Piccola ecchimosi sulla tempia sinistra, nessuna ferita. Testa leggermente inclinata a sinistra, spalle simmetriche.","a":"ecchimosi tempia postura"},{"c":2,"l":"Esame neurologico di braccia e gambe","t":"Sensibilità al tocco normale e simmetrica ai quattro arti, forza segmentale 5/5, riflessi bicipitale, tricipitale, rotuleo e achilleo presenti e simmetrici. Nessun formicolio.","k":1,"w":"Debolezza o formicolio a braccia o gambe dopo l'impatto vanno trattati come possibile lesione del rachide cervicale: va escluso prima di qualunque esercizio.","a":"neurologico sensibilità riflessi dermatomeri"},{"c":3,"l":"Cefalea","t":"4/10, temporale sinistra e retro-orbitaria; sale a 6/10 leggendo per 15 minuti o con luce forte.","a":"cefalea testa dolore"},{"c":3,"l":"Palpazione cervicale","t":"Spinose cervicali non dolenti. Dolorabilità dei muscoli suboccipitali e del trapezio superiore a sinistra; la pressione suboccipitale sinistra riproduce in parte il dolore dietro l'occhio.","k":1,"w":"Nessun dolore sulle spinose (dato che, se presente, porta alle regole del trauma cervicale); il dolore muscolare che riproduce la cefalea fa pensare a una componente cervicale da trattare.","a":"palpazione spinose suboccipitali trapezio"},{"c":4,"l":"ROM cervicale attivo","t":"Flessione completa. Estensione 50° con aumento della cefalea. Rotazione destra 70°, sinistra 60° con tensione a sinistra. Inclinazione destra 30° (tira a sinistra), sinistra 40°.","a":"mobilità rotazione inclinazione estensione cervicale"},{"c":5,"l":"Flessione cranio-cervicale","t":"Da supino annuisce controllando fino a 24 mmHg per 10 s; a 26 mmHg compensa con lo sternocleidomastoideo.","a":"craniocervicale flessori profondi biofeedback"},{"c":5,"l":"Forza del collo al dinamometro manuale","t":"Rimandata alla seconda seduta (giorno 5) perché lo sforzo massimale aumentava la cefalea. Giorno 5, seduto con il tronco fissato: flessione 14 kg (pre-stagione 19), estensione 22 kg (26), inclinazione destra 17 kg (18), sinistra 13 kg (18).","k":1,"w":"Il deficit va recuperato prima del contatto: dopo una commozione aumentano gli infortuni di testa e collo. I valori pre-stagionali sono il riferimento.","s":"Moore 2022 (PMID 36588427)","a":"dinamometro forza collo"},{"c":6,"l":"Equilibrio","t":"Su due piedi stabile. Tandem a occhi chiusi: 4 errori in 20 s (pre-stagione 1). Su una gamba a occhi chiusi: 7 errori (pre-stagione 3).","a":"equilibrio tandem monopodalico stabilità"},{"c":6,"l":"Tolleranza allo sforzo","t":"Test graduale su tapis roulant prescritto dal medico ed eseguito al giorno 3: i sintomi aumentano di 3 punti a una frequenza cardiaca di 150 bpm, dopo 9 minuti.","k":1,"w":"Individua la frequenza cardiaca a cui i sintomi aumentano: è la base per prescrivere l'esercizio aerobico sotto la soglia.","s":"Leddy 2021 (PMID 34600629)","a":"sforzo buffalo treadmill cyclette frequenza cardiaca aerobico"},{"c":6,"l":"Attività quotidiane","t":"Legge 15 minuti, poi la cefalea sale. Cammina 20 minuti senza peggioramento.","a":"lettura camminare concentrazione"},{"c":7,"l":"Segni visibili a bordo campo (CRT6)","t":"Riferiti dal fisioterapista di squadra: lento a rialzarsi, sguardo vuoto, si teneva la testa, poco stabile nel primo minuto, domande ripetute.","k":1,"w":"Il CRT6 serve a riconoscere il sospetto e togliere l'atleta dal gioco, anche da parte di chi non è sanitario: non fa diagnosi. Qui il riconoscimento è arrivato in ritardo.","s":"Patricios 2023 (PMID 37316210)","a":"crt6 bordo campo riconoscimento sospetto"},{"c":7,"l":"SCAT6 del medico a fine partita","t":"Orientamento corretto. 14 sintomi, gravità 38. Lista di 10 parole: 19/30 (pre-stagione 26). Cifre al contrario: 2/4. Esame del collo: nessun dolore centrale, rotazione completa. Equilibrio: 9 errori (pre-stagione 4).","k":1,"w":"Lo SCAT6 è utile entro 72 ore e la sua utilità cala fino a 7 giorni; la lista di 10 parole riduce l'effetto tetto. Il confronto con il valore pre-stagionale rende il dato più leggibile.","s":"Echemendia 2023 (PMID 37316213)","a":"scat6 scat valutazione medica"},{"c":7,"l":"Scala dei sintomi oggi","t":"11 sintomi su 22, gravità 26: cefalea, pressione alla testa, sensibilità alla luce, sensazione di rallentamento, nebbia, difficoltà a concentrarsi, stanchezza, sonnolenza, nausea lieve, vertigine, collo rigido.","k":1,"w":"Il carico di sintomi iniziale è il predittore più forte di un recupero lungo; ripetuta prima, durante e dopo ogni seduta serve a dosare l'esercizio.","s":"Putukian 2023 (PMID 37316183)","a":"sintomi scala punteggio gravità"},{"c":7,"l":"Screening vestibolare e oculomotorio","t":"Inseguimento lento: nessun sintomo. Saccadi orizzontali: cefalea +2. Riflesso vestibolo-oculare orizzontale con la testa in movimento: vertigine +3 e nausea +1. Convergenza: 9 cm, cefalea +1.","k":1,"w":"I sintomi provocati orientano verso esercizi vestibolari e oculomotori specifici; le soglie di positività non sono nelle fonti della scheda.","a":"vestibolare oculomotorio saccadi convergenza vertigine"},{"c":8,"l":"Imaging","t":"Nessuno. Il medico non ha ritenuto necessaria una TC: sintomi in calo, esame neurologico e del collo normali.","a":"tac risonanza radiografia esami"}]},
{"id":"collo-scossa","d":"Testa","t":"Flanker, 21 anni, scossa al braccio in placcaggio","chips":["21 anni","Flanker (6)","Serie A2","1,88 m · 102 kg","Collo e braccio destro"],"testo":"Matteo è un terza linea flanker di serie A2. Sabato ha placcato di spalla destra un avversario lanciato: nell'impatto la testa è stata spinta verso sinistra e la spalla destra verso il basso. Ha sentito una scossa bruciante dal collo fino alla mano destra e per due o tre minuti il braccio è rimasto pesante e debole. Ha scosso il braccio ed è rimasto in campo fino alla fine. Il medico della società lo ha visto domenica e ti chiede di valutarlo: oggi è martedì e Matteo dice che la presa della mano destra non gli sembra ancora la stessa.","diag":"Stinger (neuroaprassia transitoria del tronco superiore del plesso brachiale destro, C5-C6) da stiramento in placcaggio di spalla, al secondo episodio della stagione (il primo non dichiarato). Debolezza residua di presa, abduzione ed extrarotazione a destra, lieve componente compressiva radicolare C6 (Spurling positivo a destra, estensione cervicale ridotta, riduzione dello spazio discale C5-C6 all'RX) e discinesia scapolare di tipo I. Lesione midollare e instabilità cervicale escluse: sintomi solo a destra, arti inferiori normali, nessun dolore centrale, flesso-estensione stabile. Niente partita sabato: rientro guidato da sintomi, forza al dinamometro e contatto progressivo, con valutazione specialistica per la recidiva.","schede":[["stinger-burner","Stinger o burner (neuroaprassia del plesso brachiale)"]],"items":[{"c":0,"l":"Meccanismo del trauma","t":"«Ho placcato di spalla destra un avversario che arrivava forte. Nell'impatto la testa mi è andata di colpo verso sinistra e la spalla destra è stata schiacciata verso il basso.»","k":1,"w":"Testa spinta di lato e spalla abbassata è il meccanismo di stiramento del plesso: orienta verso uno stinger e lo distingue dalla compressione della radice con il collo esteso e inclinato verso il lato dei sintomi.","a":"dinamica placcaggio spalla stiramento"},{"c":0,"l":"Sintomi al momento dell'impatto","t":"«Una scossa elettrica che bruciava, dalla base del collo alla spalla e giù fino al pollice destro. Per due o tre minuti il braccio era morto: non riuscivo ad alzarlo né a stringere bene la mano. Poi è tornato quasi normale.»","k":1,"w":"Scossa, bruciore e debolezza in un solo braccio che recuperano in pochi minuti sono il quadro tipico dello stinger, di solito del tronco superiore.","s":"Ahearn 2019 (PMID 30741724)","a":"scossa bruciore burner stinger intorpidimento"},{"c":0,"l":"Lato dei sintomi, altro braccio e gambe","t":"«Solo il braccio destro. Il sinistro e le gambe erano normali: ho continuato a correre senza problemi.»","k":1,"w":"Sintomi a entrambe le braccia o alle gambe, anche se passano in fretta, non sono uno stinger: vanno gestiti come possibile lesione midollare, con immobilizzazione e soccorsi.","a":"bilaterale bilateralità midollo midollare gambe sinistro"},{"c":0,"l":"Dolore al collo dopo l'impatto","t":"«Un po' di indolenzimento sul lato destro del collo, niente dolore in mezzo dietro. Giravo la testa normalmente già in campo.»","a":"dolore collo cervicale centrale"},{"c":0,"l":"Coscienza e sintomi di commozione","t":"«Non ho preso colpi in testa. Mai confuso, niente mal di testa, nausea o vista annebbiata.»","k":1,"w":"Un'alterazione della coscienza o sintomi di commozione associati cambiano la gestione: l'atleta va valutato anche per commozione.","a":"commozione coscienza cefalea confusione"},{"c":0,"l":"Sintomi residui","t":"«Il bruciore è passato in pochi minuti. Da domenica però la presa a destra è più debole: faccio fatica ad aprire i barattoli e a tenere la maglia nel ruck. Se guardo in alto a lungo sento un formicolio leggero al pollice destro.»","k":1,"w":"La debolezza della presa è il sintomo più duraturo nei giovani rugbisti; una debolezza che persiste o non migliora nei giorni successivi richiede la valutazione medica.","s":"Kawasaki 2015 (PMID 26337244)","a":"debolezza presa formicolio persistenti residui"},{"c":0,"l":"Episodi precedenti","t":"«A settembre una scossa uguale allo stesso braccio, durata un minuto. Anche la scorsa stagione una volta. In tutte e due le volte l'impatto era meno forte di sabato.»","k":1,"w":"Lo stinger precedente è il fattore di rischio più forte per nuovi episodi e per sintomi più lunghi; episodi ripetuti nella stessa stagione richiedono una valutazione specialistica prima di tornare.","s":"Kawasaki 2015 (PMID 26337244)","a":"recidiva precedenti ricorrenti storia"},{"c":0,"l":"Episodi riferiti allo staff","t":"«A settembre non l'ho detto a nessuno: ho scosso il braccio e sono andato avanti, pensavo fosse normale.»","a":"dichiarato riferito staff medico"},{"c":0,"l":"Salute generale e farmaci","t":"«Nessuna malattia, niente farmaci. Niente febbre o perdita di peso.»","a":"farmaci salute generale"},{"c":0,"l":"Ruolo e carico","t":"«Flanker, 15-20 placcaggi a partita, quattro allenamenti a settimana. Sabato c'è la partita.»","a":"placcaggi allenamenti partita"},{"c":1,"l":"Ispezione di collo, spalle e braccio","t":"Spalle allo stesso livello, nessuna atrofia del deltoide, del sovraspinato o dell'infraspinato a destra. Collo in posizione neutra, nessuna tumefazione.","k":1,"w":"Un'atrofia di spalla e braccio indica un danno nervoso più importante: richiede valutazione medica, eventuale elettromiografia e imaging.","a":"atrofia trofismo deltoide ispezione"},{"c":2,"l":"Sensibilità di braccio e mano","t":"Lieve riduzione della sensibilità al tocco sulla faccia laterale della spalla destra (8/10 rispetto alla sinistra). Pollice, mano e braccio sinistro normali.","a":"sensibilità dermatomeri ipoestesia c5 c6"},{"c":2,"l":"Riflessi degli arti superiori","t":"Bicipitale destro un po' ridotto rispetto al sinistro; brachioradiale e tricipitale presenti e simmetrici.","a":"riflessi bicipitale brachioradiale"},{"c":2,"l":"Esame neurologico degli arti inferiori","t":"Forza, sensibilità e riflessi normali e simmetrici, nessun segno di interessamento del midollo (Babinski e Hoffmann negativi), cammino in tandem regolare.","k":1,"w":"Va controllato sempre: qualunque segno agli arti inferiori è una red flag di possibile lesione del midollo, non uno stinger.","a":"arti inferiori gambe babinski hoffmann midollo"},{"c":3,"l":"Palpazione del collo","t":"Spinose cervicali non dolenti. Dolorabilità degli scaleni e del trapezio superiore a destra e al punto sopraclaveare destro.","k":1,"w":"Dolore centrale o dolorabilità sulle spinose porterebbero alle regole del trauma cervicale; la dolorabilità laterale e sopraclaveare è coerente con lo stiramento del plesso.","a":"spinose palpazione scaleni sopraclaveare"},{"c":3,"l":"Dolore attuale","t":"2/10 sul lato destro del collo, solo a fine movimento; nessun dolore al braccio a riposo.","a":"dolore intensità"},{"c":4,"l":"ROM cervicale (inclinometro)","t":"Flessione completa. Estensione 50° con formicolio al pollice destro a fine range. Rotazione destra 70°, sinistra 75°. Inclinazione destra 35° con formicolio al pollice, sinistra 40° con tensione sul lato destro.","k":1,"w":"Una minore estensione cervicale si associa a una storia di stinger: va registrata, non è una soglia diagnostica. Il range che provoca sintomi guida la mobilità nelle prime fasi.","s":"Hakkaku 2017 (PMID 29147669)","a":"mobilità rotazione inclinazione estensione inclinometro"},{"c":4,"l":"ROM della spalla","t":"Completo e simmetrico in tutte le direzioni.","a":"spalla articolarità"},{"c":5,"l":"Forza del braccio al dinamometro manuale","t":"Presa destra 44 kg, sinistra 55 kg (LSI 80%). Abduzione 17 kg contro 21 kg (81%). Extrarotazione 13 kg contro 15,5 kg (84%). Flessione del gomito 22 kg contro 24 kg (92%).","k":1,"w":"Serve a monitorare il recupero: la presa è il deficit più duraturo. L'LSI ≥90% come criterio di rientro è una proposta operativa.","s":"Kawasaki 2015 (PMID 26337244)","a":"dinamometro forza presa abduzione extrarotazione"},{"c":5,"l":"Forza del collo al dinamometro manuale","t":"Seduto con il tronco fissato: flessione 16 kg, estensione 25 kg, inclinazione destra 17 kg, sinistra 21 kg. Pre-stagione: 18, 27, 20 e 20 kg.","a":"forza collo dinamometro"},{"c":6,"l":"Prove funzionali dell'arto superiore","t":"20 piegamenti completi, ma negli ultimi il braccio destro trema. Appeso alla sbarra 38 s, poi molla per primo la destra (pre-stagione 60 s).","a":"piegamenti sbarra funzione"},{"c":7,"l":"Spurling","t":"A destra riproduce il formicolio al pollice, senza dolore forte al braccio; a sinistra negativo. Eseguito solo dopo che il medico ha escluso frattura e instabilità.","k":1,"w":"I sintomi riprodotti indicano una componente compressiva della radice oltre allo stiramento; non va fatto a bordo campo in fase acuta. Spurling negativo è tra i criteri di rientro proposti.","a":"spurling compressione foraminale radice"},{"c":7,"l":"Osservazione della scapola","t":"Con 2 kg in mano, nell'abbassamento del braccio destro l'angolo inferiore della scapola si stacca dal torace (discinesia di tipo I). A sinistra normale.","k":1,"w":"La discinesia di tipo I si associa a una storia di stinger con dolore irradiato alla spalla: è uno studio trasversale, non dimostra una causa, ma indica un lavoro sulla scapola.","s":"Kawasaki 2014 (PMID 24957846)","a":"scapola discinesia scapolare"},{"c":7,"l":"Test di tensione neurale dell'arto superiore","t":"A destra formicolio sulla faccia laterale dell'avambraccio con il gomito ancora a 25° dall'estensione completa; a sinistra solo tensione a fine range.","a":"tensione neurale neurodinamico ultt plesso"},{"c":8,"l":"Radiografia cervicale","t":"Chiesta dal medico per il secondo episodio: lieve riduzione dello spazio discale C5-C6, nessuna frattura, nessuna instabilità nelle proiezioni in flessione ed estensione. Risonanza magnetica in programma con lo specialista.","k":1,"w":"Negli episodi ripetuti o con deficit persistenti l'imaging aiuta le decisioni di rientro, ma i valori soglia non sono validati. La degenerazione discale si associa a una storia di stinger.","s":"Bowles 2020 (PMID 32691363); Hakkaku 2017 (PMID 29147669)","a":"radiografia risonanza imaging esami"},{"c":8,"l":"Elettromiografia","t":"Non eseguita. Il medico la richiederà se la debolezza non migliora nelle prossime settimane.","a":"elettromiografia emg"}]},
{"id":"spalla-caduta","d":"Spalla","t":"Tallonatore, 27 anni, spalla dopo una caduta","chips":["27 anni","Tallonatore (2)","Serie A2","1,78 m · 104 kg","Spalla sinistra (non dominante)"],"testo":"Marco è il tallonatore titolare di una squadra di serie A2. Sabato, a metà del primo tempo, è stato placcato in corsa da un avversario che lo ha spinto di lato: è caduto a terra direttamente sulla punta della spalla sinistra, con il braccio lungo il fianco. È rimasto in campo ancora qualche minuto, poi è uscito perché non riusciva a legarsi in mischia. In pronto soccorso gli hanno fatto le radiografie e gli hanno dato un tutore a fascia. Oggi è martedì: arriva con il tutore, che toglie da solo per la visita.","diag":"Distorsione acromion-claveare sinistra di grado II secondo Rockwood: legamenti acromion-claveari rotti, coraco-claveari distorti ma integri, lieve sollevamento della clavicola senza spostamento posteriore. Nessuna frattura di clavicola, acromion o coracoide; cute integra, nessun deficit neurovascolare. Trattamento conservativo: tutore solo per comfort e per pochi giorni, poi recupero di ROM e forza e progressione verso spinta, cadute e contatto guidata dai criteri.","schede":[["spalla-ac","Distorsione acromion-claveare"]],"items":[{"c":0,"l":"Meccanismo del trauma","t":"«Mi hanno placcato di lato mentre correvo con la palla. Sono caduto di peso sulla punta della spalla sinistra, con il braccio attaccato al corpo. Non ho messo la mano avanti per pararmi.»","k":1,"w":"La caduta diretta sulla punta della spalla con il braccio addotto è il meccanismo tipico della lesione acromion-claveare; la caduta sulla mano tesa orienterebbe di più verso clavicola o gleno-omerale.","a":"dinamica caduta placcaggio"},{"c":0,"l":"Cosa ha sentito al momento","t":"«Un dolore secco in cima alla spalla, 8/10. Non ho sentito la spalla uscire e non ho avuto la sensazione che il braccio fosse fuori posto.»","a":"schiocco dolore iniziale lussazione"},{"c":0,"l":"Sede del dolore","t":"«Proprio in cima alla spalla, dove c'è l'osso che sporge. Ci metto un dito sopra e fa male lì.»","k":1,"w":"Il paziente indica con un dito l'articolazione acromion-claveare: un dolore così localizzato orienta verso l'AC più che verso clavicola o cuffia.","a":"dove localizzazione punto"},{"c":0,"l":"Andamento del dolore","t":"«Sabato sera 7/10. Oggi a riposo 2/10, quando alzo il braccio o lo porto verso l'altra spalla arrivo a 6/10.»","a":"vas nrs peggioramento miglioramento"},{"c":0,"l":"Sonno e decubito","t":"«Non riesco a dormire sul lato sinistro: mi sveglio se mi giro sopra la spalla.»","a":"notte dormire decubito"},{"c":0,"l":"Formicolii o debolezza al braccio","t":"«No, nessun formicolio. La mano la sento normale.»","k":1,"w":"Il deficit neurovascolare è una red flag della scheda: va chiesto e poi controllato all'esame.","a":"formicolio parestesie neurologico"},{"c":0,"l":"Infortuni precedenti alla spalla","t":"«Alla spalla sinistra mai niente. Alla destra una distorsione dell'acromion due anni fa, guarita in un mese.»","a":"storia pregressa precedenti"},{"c":0,"l":"Lato dominante e ruolo","t":"«Sono destro. Da tallonatore lancio in touche con tutte e due le mani, mi lego in mischia con il braccio sinistro sopra il pilone e placco tanto.»","k":1,"w":"Il lato non dominante e le richieste del ruolo (legatura in mischia, lancio, placcaggio) pesano sulla decisione e sugli obiettivi di rientro.","a":"dominanza mischia touche legatura"},{"c":0,"l":"Cosa è stato fatto finora","t":"«Pronto soccorso sabato: radiografie e tutore a fascia. Mi hanno detto ghiaccio e di toglierlo quando sto meglio. Da domenica prendo un anti-infiammatorio.»","a":"trattamenti pronto soccorso tutore farmaci"},{"c":0,"l":"Salute generale","t":"«Sto bene, nessuna malattia, niente febbre.»","a":"generale anamnesi remota"},{"c":1,"l":"Ispezione della spalla in piedi","t":"Piccolo scalino visibile sopra la spalla sinistra: l'estremità laterale della clavicola appare un po' più alta dell'acromion rispetto al lato destro. Lieve gonfiore locale, ecchimosi modesta sul deltoide anteriore. Nessuna deformità a metà della clavicola.","k":1,"w":"Lo scalino lieve fa pensare a un grado II-III; uno scalino marcato o una clavicola spinta indietro farebbero pensare ai gradi IV-V, da consulto chirurgico.","a":"scalino gradino deformità ispezione"},{"c":1,"l":"Condizione della cute sopra l'articolazione","t":"Cute integra, non tesa, non pallida e senza abrasioni profonde.","k":1,"w":"Una cute minacciata dalla clavicola sporgente è una red flag della scheda e richiede invio urgente.","a":"pelle cute minacciata"},{"c":1,"l":"Postura e scapola","t":"Spalla sinistra lievemente abbassata e protratta; braccio tenuto vicino al tronco.","a":"scapola postura"},{"c":2,"l":"Sensibilità di spalla, braccio e mano","t":"Normale e simmetrica, compresa la zona laterale del deltoide.","a":"neurologico dermatomeri sensibilità"},{"c":2,"l":"Polso radiale e riempimento capillare","t":"Presenti e simmetrici.","a":"vascolare circolo polso"},{"c":3,"l":"Palpazione dell'articolazione acromion-claveare","t":"Dolore vivo, 7/10, sulla rima acromion-claveare sinistra, con lieve edema locale.","k":1,"w":"Il dolore alla palpazione della rima conferma la sede della lesione.","a":"palpazione acromion claveare"},{"c":3,"l":"Palpazione della clavicola lungo tutta la diafisi","t":"Diafisi e terzo medio non dolenti, nessuna crepitazione né scalino osseo lungo il decorso.","k":1,"w":"Serve a escludere la frattura di clavicola, che con questo meccanismo è la principale diagnosi alternativa e richiede un'altra gestione.","a":"clavicola frattura diafisi"},{"c":3,"l":"Palpazione della coracoide e dello spazio coraco-claveare","t":"Lieve dolorabilità sotto la clavicola, verso la coracoide.","a":"coracoide coraco claveari"},{"c":3,"l":"Palpazione di grande tubercolo e solco bicipitale","t":"Non dolenti.","a":"cuffia bicipite tubercolo"},{"c":1,"l":"Rachide cervicale","t":"Mobilità completa e indolore, nessun dolore irradiato.","a":"cervicale collo"},{"c":4,"l":"Mobilità attiva","t":"Flessione: sinistra 140° con dolore in cima negli ultimi gradi, destra 175°. Abduzione: sinistra 120° con dolore sopra i 90°. Extrarotazione a braccio lungo il corpo simmetrica e indolore.","a":"rom attiva flessione abduzione"},{"c":4,"l":"Mobilità passiva","t":"Flessione 160° con dolore in cima; adduzione orizzontale passiva limitata dal dolore.","a":"passiva"},{"c":4,"l":"Intrarotazione (mano dietro la schiena)","t":"Sinistra fino a L3 con dolore in cima, destra fino a T8.","a":"intrarotazione"},{"c":5,"l":"Forza al dinamometro manuale","t":"Abduzione: sinistra 9 kg con dolore, destra 15 kg. Extrarotazione: sinistra 11 kg, destra 13 kg.","k":1,"w":"È il valore di partenza per il criterio di forza della scheda (abduzione ed ER ≥90-95% del lato sano, valore operativo); ricorda che anche il lato sano può essere decondizionato.","a":"dinamometro hhd abduzione extrarotazione"},{"c":5,"l":"Forza dei muscoli scapolari","t":"Trapezio inferiore e dentato anteriore deboli a sinistra, test resistiti senza dolore.","a":"scapola trapezio dentato"},{"c":6,"l":"Push-up inclinato al tavolo","t":"Eseguito con dolore 5/10 in cima alla spalla nell'ultima parte della discesa; 4 ripetizioni.","k":1,"w":"Valuta la tolleranza alla spinta e al carico in appoggio, alla base della fase SSC e del criterio di dolore e funzione.","a":"piegamenti appoggio push"},{"c":6,"l":"Attività quotidiane","t":"«Mi vesto da solo ma la maglia la infilo prima dal braccio sinistro. Non riesco a portare la borsa a tracolla.»","a":"quotidiane vestirsi"},{"c":7,"l":"Palpazione e stabilità della clavicola","t":"Traslazione antero-posteriore della clavicola aumentata rispetto al lato destro, dolorosa; minima mobilità verticale. Nessuno spostamento posteriore.","k":1,"w":"L'instabilità orizzontale o verticale guida il grado e l'eventuale consulto ortopedico, come indica la scheda.","a":"stabilità traslazione orizzontale verticale"},{"c":7,"l":"Cross-body adduction","t":"Positivo: dolore sull'acromion-claveare sinistra, 6/10.","k":1,"w":"Il dolore sull'AC con l'adduzione orizzontale suggerisce coinvolgimento articolare; è anche il gesto da evitare all'inizio.","a":"cross body adduzione orizzontale"},{"c":7,"l":"O'Brien (active compression)","t":"Dolore superficiale in cima alla spalla in rotazione interna, ridotto in supinazione. Nessun dolore profondo.","k":1,"w":"Dolore in cima orienta verso l'AC, dolore profondo verso SLAP; per la SLAP il test da solo non basta perché i dati dello studio originale non sono stati confermati.","s":"Hegedus 2012 (PMID 22773322)","a":"obrien compressione attiva slap"},{"c":7,"l":"Test per la cuffia e per l'instabilità gleno-omerale","t":"Jobe e extrarotazione resistita senza perdita di forza; apprensione negativa; drop arm negativo.","a":"cuffia jobe apprensione"},{"c":8,"l":"Radiografia del pronto soccorso","t":"Nessuna frattura di clavicola, acromion o coracoide. Estremità laterale della clavicola lievemente sollevata rispetto all'acromion; distanza coraco-claveare poco aumentata rispetto al lato destro.","k":1,"w":"Imaging e stabilità definiscono il grado Rockwood ed escludono la frattura: qui il quadro è compatibile con un grado II.","a":"radiografia rx frattura"},{"c":8,"l":"Proiezione assiale","t":"Nessuno spostamento posteriore della clavicola.","k":1,"w":"Lo spostamento posteriore nel trapezio definisce il grado IV, da consulto chirurgico.","a":"assiale posteriore trapezio"}]},
{"id":"dito-maglia","d":"Mano","t":"Seconda linea, 24 anni, dito dopo una presa sulla maglia","chips":["24 anni","Seconda linea (5)","Serie A2","1,98 m · 115 kg","Mano destra (dominante), anulare"],"testo":"Andrea è una seconda linea di serie A2. Domenica, nel finale di partita, ha provato a fermare un'ala avversaria che gli passava accanto afferrandola per la maglia con la mano destra: l'avversario ha accelerato e la maglia gli è stata strappata dalle dita. Ha sentito un dolore all'anulare, ma ha finito la partita. Il medico della società ha parlato di «dito slogato» e gli ha consigliato di legarlo al medio. Oggi è giovedì e viene da te perché il dito è ancora gonfio e non riesce a chiudere bene il pugno.","diag":"Avulsione chiusa del tendine del flessore profondo (FDP) dell'anulare destro (jersey finger), tipo II di Leddy-Packer: moncone retratto all'altezza della interfalangea prossimale, nessun frammento osseo. Flessione attiva dell'IFD assente. Indicazione all'invio rapido al chirurgo della mano per la riparazione: non va trattato come una distorsione o un dito a martello. Dopo la riparazione, riabilitazione per fasi secondo il protocollo del chirurgo e rientro guidato dai criteri.","schede":[["jersey-finger","Jersey finger (avulsione del flessore profondo)"]],"items":[{"c":0,"l":"Meccanismo del trauma","t":"«Ho afferrato la maglia dell'ala con la destra, tenendo forte con le punte delle dita. Lui ha accelerato e la maglia mi è scappata di mano tirandomi l'anulare in fuori.»","k":1,"w":"Il dito flesso esteso con forza mentre afferra la maglia è il meccanismo tipico dell'avulsione del flessore profondo.","a":"dinamica maglia afferrare presa"},{"c":0,"l":"Dito colpito","t":"«L'anulare destro. Le altre dita stanno bene.»","k":1,"w":"L'anulare è il dito coinvolto nella grande maggioranza dei casi (circa 80% nella scheda).","s":"Fontès 2026 (PMID 41654031)","a":"anulare quarto dito"},{"c":0,"l":"Cosa ha sentito al momento","t":"«Un dolore secco, come uno strappo, 6/10. Poi è calato e ho finito la partita.»","a":"strappo dolore iniziale"},{"c":0,"l":"Tempo trascorso dal trauma","t":"«È successo domenica pomeriggio: sono passati quattro giorni.»","k":1,"w":"Con il ritardo il tendine si retrae e la riparazione diventa più difficile: il tempo trascorso decide l'urgenza dell'invio.","s":"Hilgefort 2025 (PMID 40736493)","a":"giorni tempistica ritardo"},{"c":0,"l":"Cosa non riesce a fare","t":"«Non riesco a chiudere del tutto il pugno: la punta dell'anulare resta fuori. Faccio fatica ad abbottonarmi la camicia.»","k":1,"w":"La perdita della flessione della punta del dito è il sintomo chiave; spesso viene confusa con una distorsione.","a":"pugno chiudere punta"},{"c":0,"l":"Dolore oggi","t":"«A riposo 2/10. Se premo sul palmo alla base del dito o provo a stringere, 5/10.»","a":"vas nrs dolore attuale"},{"c":0,"l":"Cosa è stato fatto finora","t":"«Ghiaccio e il dito legato al medio con il cerotto. Nessuna radiografia.»","a":"trattamenti taping ghiaccio"},{"c":0,"l":"Infortuni precedenti alla mano","t":"«Una frattura del quinto metacarpo sinistro tre anni fa. Alla destra niente.»","a":"storia pregressa precedenti"},{"c":0,"l":"Mano dominante e richieste del ruolo","t":"«Sono destro. In seconda linea mi lego in mischia, prendo la palla in touche e afferro tanto le maglie nel maul e nel ruck.»","a":"dominanza touche mischia legatura"},{"c":1,"l":"Cascata delle dita a riposo","t":"Mano rilassata con il palmo in alto: l'anulare destro resta più esteso delle altre dita, in particolare alla interfalangea distale.","k":1,"w":"La perdita della normale cascata in flessione è un segno della lesione del flessore, visibile prima di toccare il paziente.","a":"cascata riposo atteggiamento"},{"c":1,"l":"Gonfiore ed ecchimosi","t":"Gonfiore lieve sul lato palmare della falange intermedia e della IFP dell'anulare, ecchimosi modesta. Nessuna ferita.","k":1,"w":"Una ferita palmare indicherebbe una lesione aperta del flessore, con rischio di infezione: red flag della scheda.","a":"edema livido ferita"},{"c":1,"l":"Unghia e dorso del dito","t":"Unghia integra, nessuna deformità a martello dell'IFD.","a":"martello unghia dorso"},{"c":2,"l":"Sensibilità dei polpastrelli","t":"Normale e simmetrica sui lati radiale e ulnare dell'anulare e delle altre dita.","a":"nervi digitali sensibilità"},{"c":2,"l":"Colore, temperatura e riempimento capillare del dito","t":"Dito roseo, caldo, riempimento capillare normale.","k":1,"w":"Un dito pallido, freddo o insensibile è una red flag della scheda.","a":"vascolare circolo colorito"},{"c":3,"l":"Palpazione lungo il flessore","t":"Dolore lungo il lato palmare della falange intermedia; nodulo dolente palpabile all'altezza della IFP. Nessun nodulo nel palmo.","k":1,"w":"Il nodulo indica il livello del moncone retratto: all'altezza della IFP orienta verso un tipo II; un nodulo nel palmo (tipo I) aumenterebbe l'urgenza.","a":"palpazione nodulo moncone"},{"c":3,"l":"Palpazione della falange distale","t":"Lieve dolore sulla base palmare della falange distale, nessuno scalino osseo.","a":"falange distale inserzione"},{"c":3,"l":"Palpazione delle altre dita e del polso","t":"Non dolenti.","a":"polso dita"},{"c":4,"l":"Mobilità attiva dell'anulare","t":"Metacarpo-falangea 0-85°. IFP 0-90°. IFD: nessuna flessione attiva. Altre dita normali.","k":1,"w":"Documenta il deficit e serve da misura per il ROM attivo totale dopo la riparazione.","a":"rom attiva goniometro"},{"c":4,"l":"Mobilità passiva dell'IFD","t":"Flessione passiva 0-65°, completa e lievemente dolente.","k":1,"w":"La flessione passiva conservata con quella attiva assente indica che il problema è il tendine, non l'articolazione bloccata.","a":"passiva rigidità"},{"c":5,"l":"Flessione isolata della IFP (superficiale)","t":"Con le altre dita tenute in estensione l'anulare flette la IFP con forza buona.","a":"superficiale fds flessore superficiale"},{"c":5,"l":"Forza di presa al dinamometro","t":"Destra 38 kg con dolore all'anulare, sinistra 56 kg.","k":1,"w":"Valore di partenza; nel rientro la forza di presa è un criterio (almeno 80-90% del lato sano, proposta operativa). Non va spinta al massimo prima della riparazione.","a":"dinamometro presa grip"},{"c":6,"l":"Prese funzionali","t":"Presa a uncino debole sull'anulare; presa della palla possibile ma l'anulare non avvolge la palla.","a":"uncino palla funzionale"},{"c":6,"l":"Attività quotidiane","t":"«Uso la mano ma tengo l'anulare un po' fuori. Abbottonarmi e prendere oggetti piccoli è scomodo.»","a":"quotidiane vestirsi"},{"c":7,"l":"Flessione isolata dell'IFD","t":"IFP bloccata in estensione: nessuna flessione attiva della punta dell'anulare. Sulle altre dita la flessione è presente.","k":1,"w":"È il segno chiave: la flessione dell'IFD assente con la IFP bloccata indica la lesione del flessore profondo.","a":"flessione isolata flessore profondo blocco ifd"},{"c":7,"l":"Differenziale con il dito a martello","t":"Estensione attiva dell'IFD completa.","k":1,"w":"Il dito a martello (estensore) si tratta con lo splint; il jersey finger va inviato al chirurgo della mano: confonderli fa perdere tempo.","s":"Hilgefort 2025 (PMID 40736493)","a":"martello mallet estensore differenziale"},{"c":7,"l":"Stabilità dei collaterali della IFP e IFD","t":"Stress in varo e valgo stabile e poco doloroso.","a":"collaterali stabilità"},{"c":8,"l":"Radiografia del dito (su indicazione medica)","t":"Nessun frammento osseo alla base della falange distale, nessuna frattura.","k":1,"w":"L'RX cerca un frammento osseo, presente nei tipi III-V, che cambia la tecnica chirurgica.","a":"radiografia rx frammento"},{"c":8,"l":"Ecografia","t":"Tendine del flessore profondo non visibile all'inserzione; moncone retratto all'altezza della IFP. Flessore superficiale integro.","k":1,"w":"Ecografia o RM definiscono il livello di retrazione, che orienta l'urgenza e la tecnica di riparazione.","a":"ecografia risonanza retrazione"}]},
{"id":"ginocchio-ruck","d":"Ginocchio","t":"Pilone, 29 anni, ginocchio in una ruck","chips":["29 anni","Pilone (3)","Serie A2","1,84 m · 118 kg","Ginocchio destro"],"testo":"Riccardo è un pilone destro di serie A2. Sabato, in una ruck, aveva il piede destro piantato e il peso in avanti quando un avversario gli è crollato addosso sul lato esterno del ginocchio destro. Ha sentito un dolore forte all'interno del ginocchio, ha provato a continuare per qualche minuto ed è uscito alla fine del primo tempo. Ha messo ghiaccio e una fasciatura elastica, senza fare esami. Oggi è lunedì e viene da te camminando: zoppica e non stende del tutto il ginocchio.","diag":"Lesione di II grado isolata del legamento collaterale mediale destro, prossimale (inserzione femorale): lassità in valgo a 30° con arresto netto, stabile a 0°. LCA, LCP, menischi e angolo postero-mediale integri, nessuna frattura. Percorso conservativo con protezione dal valgo e progressione per criteri; tempi orientativi del grado II 3-6 settimane.","schede":[["ginocchio-lcm","Lesione del legamento collaterale mediale (LCM)"]],"items":[{"c":0,"l":"Meccanismo del trauma","t":"«Ero chiuso nella ruck, piede destro piantato e tutto il peso avanti. Uno dei loro è caduto di peso sul lato esterno del mio ginocchio destro: il ginocchio è andato verso l'interno e il piede è rimasto fermo. Non mi sono girato, mi hanno schiacciato.»","k":1,"w":"Un colpo dall'esterno a piede fisso spinge il ginocchio in valgo: è il meccanismo tipico della lesione del LCM. La mancanza di una rotazione del corpo sul piede rende meno probabile, ma non esclude, un LCA associato.","a":"dinamica valgo contatto"},{"c":0,"l":"Cosa ha sentito al momento","t":"«Uno strappo, come una bruciatura, sul lato interno. Nessuno schiocco dentro il ginocchio e non ho avuto la sensazione che uscisse e rientrasse.»","a":"schiocco strappo cedimento"},{"c":0,"l":"Comparsa del gonfiore","t":"«Il gonfiore è venuto piano, la sera, soprattutto sul lato interno. Il ginocchio non è diventato un pallone.»","a":"gonfiore versamento emartro"},{"c":0,"l":"Capacità di continuare e camminare","t":"«Ho fatto ancora cinque o sei minuti, ma in mischia non riuscivo a spingere bene con la destra. Sono uscito camminando da solo, zoppicando.»","a":"continuare camminare carico"},{"c":0,"l":"Blocchi e cedimenti da sabato","t":"«Non si è mai bloccato. Non mi ha mai ceduto, ma non mi fido a girarmi sulla destra e sento male se il ginocchio va verso l'interno.»","k":1,"w":"Un ginocchio veramente bloccato è una red flag della scheda e farebbe sospettare una lesione meniscale da inviare presto; i cedimenti in rotazione farebbero cercare un LCA.","a":"blocco cedimento instabilità"},{"c":0,"l":"Dolore","t":"«A riposo 2/10. Camminando 4/10, scendendo le scale 6/10. Se provo a stendere tutto il ginocchio tira forte all'interno.»","a":"vas nrs dolore"},{"c":0,"l":"Infortuni precedenti","t":"«Due anni fa una distorsione al ginocchio sinistro, nulla di grave. Il destro non l'ho mai fatto male.»","a":"storia pregressa precedenti"},{"c":0,"l":"Farmaci e salute generale","t":"«Un antinfiammatorio sabato e domenica. Sto bene, nessuna malattia, niente febbre.»","a":"farmaci fans salute"},{"c":0,"l":"Ruolo e richieste di gioco","t":"«Pilone destro: mischia ordinata, ruck, placcaggi, tante spinte. Corro poco ma faccio tanti contatti.»","a":"mischia pilone richieste"},{"c":1,"l":"Ispezione del ginocchio","t":"Gonfiore localizzato sul lato mediale, sopra la rima articolare e verso il condilo femorale. Piccola ecchimosi mediale. Nessuna deformità, pelle integra. Profili della rotula ben visibili.","a":"ispezione gonfiore ecchimosi"},{"c":1,"l":"Stroke test (versamento)","t":"Grado traccia: una piccola onda compare solo dopo il secondo passaggio. A sinistra assente.","k":1,"w":"Un versamento minimo con gonfiore extra-articolare mediale va d'accordo con una lesione isolata del LCM; un versamento grande farebbe pensare a una lesione combinata (LCA, menisco).","a":"versamento stroke effusione"},{"c":1,"l":"Cammino","t":"Zoppia di fuga a destra: appoggio più breve, ginocchio tenuto flesso di circa 10° per tutto l'appoggio, evita di spingere sull'avampiede.","a":"andatura zoppia"},{"c":2,"l":"Sensibilità di gamba e piede","t":"Normale e simmetrica, anche sul lato mediale della gamba.","a":"neurologico sensibilità safeno"},{"c":2,"l":"Polsi distali","t":"Pedidio e tibiale posteriore presenti e simmetrici, piede caldo.","k":1,"w":"Il trauma multiligamentoso e il deficit vascolare sono red flag della scheda: il circolo va controllato sempre dopo un colpo violento sul ginocchio.","a":"vascolare polsi"},{"c":3,"l":"Palpazione del LCM all'inserzione femorale","t":"Dolore vivo 7/10 sull'epicondilo mediale e subito sotto, per circa 3 cm.","k":1,"w":"Localizza la sede della lesione lungo il legamento: qui prossimale.","a":"collaterale mediale epicondilo"},{"c":3,"l":"Palpazione del LCM all'inserzione tibiale","t":"Lieve fastidio, nessun dolore vivo.","a":"tibiale distale"},{"c":3,"l":"Palpazione delle rime articolari","t":"Rima mediale: lieve dolore nel tratto anteriore, vicino al legamento. Rima laterale: non dolente.","k":1,"w":"La scheda chiede di cercare lesioni meniscali associate: il dolore va distinto da quello del legamento, che sta sopra la rima.","a":"rima menisco joint line"},{"c":3,"l":"Palpazione dell'angolo postero-mediale","t":"Non dolente.","a":"postero mediale semimembranoso"},{"c":3,"l":"Palpazione di LCL, testa del perone e rotula","t":"Non dolenti.","a":"laterale perone rotula"},{"c":4,"l":"Estensione e flessione del ginocchio","t":"Estensione: destra -8° con dolore mediale a fine corsa, sinistra +2°. Flessione: destra 115° con tensione mediale, sinistra 140°.","k":1,"w":"Il recupero del ROM è l'obiettivo della prima fase; nei primi giorni l'estensione completa tira sul LCM e va recuperata gradualmente.","a":"rom estensione flessione goniometro"},{"c":5,"l":"Quadriceps lag test","t":"Lag di 5°: da seduto manca l'ultimo tratto di estensione attiva rispetto al passivo.","k":1,"w":"Togliere il quad lag è un obiettivo della prima fase del percorso della scheda; criterio preso dal protocollo post-operatorio per il grado III (Logan 2016) che la scheda usa anche nelle fasi del conservativo.","s":"Logan 2016 (PMID 27999730)","a":"lag quadricipite"},{"c":5,"l":"Forza del quadricipite al dinamometro (ginocchio a 60°)","t":"Destra 31 kg con dolore mediale 4/10, sinistra 49 kg. LSI circa 63%.","k":1,"w":"Dà il punto di partenza per la LSI, che è un criterio di passaggio tra le fasi (oltre l'80% e poi oltre il 90%); criterio preso dal protocollo post-operatorio per il grado III (Logan 2016) che la scheda usa anche nelle fasi del conservativo.","s":"Logan 2016 (PMID 27999730)","a":"dinamometro hhd forza quadricipite"},{"c":5,"l":"Forza degli abduttori d'anca","t":"Destra 25 kg, sinistra 27 kg.","a":"abduttori glutei anca"},{"c":6,"l":"Squat bipodalico","t":"Fino a circa 60° di flessione, carico spostato a sinistra, dolore mediale 3/10.","a":"squat accosciata"},{"c":6,"l":"Squat monopodalico isometrico a 45°","t":"Non eseguibile oggi a destra per dolore. A sinistra 90 secondi senza valgo.","k":1,"w":"Tenere 90 secondi lo squat monopodalico a 45° è il criterio per passare dalla fase di endurance a quella di forza; criterio preso dal protocollo post-operatorio per il grado III (Logan 2016) che la scheda usa anche nelle fasi del conservativo.","s":"Logan 2016 (PMID 27999730)","a":"squat monopodalico isometrico"},{"c":6,"l":"Y-balance test","t":"Rimandato: non tollera ancora il carico monopodalico.","k":1,"w":"La differenza tra i lati (sotto 8 cm, poi sotto 5 cm, poi composito oltre il 94%) è un criterio di fase e di rientro: va misurato quando il carico è tollerato; criterio preso dal protocollo post-operatorio per il grado III (Logan 2016) che la scheda usa anche nelle fasi del conservativo.","s":"Logan 2016 (PMID 27999730)","a":"ybalance equilibrio"},{"c":7,"l":"Stress in valgo a 0°","t":"Stabile, con dolore mediale ma senza apertura rispetto al lato sinistro.","k":1,"w":"Se il ginocchio si aprisse anche in estensione la lesione non sarebbe isolata: sarebbero coinvolti anche crociati o capsula.","a":"valgo stress estensione"},{"c":7,"l":"Stress in valgo a 30°","t":"Apertura mediale aumentata rispetto a sinistra, con dolore 6/10 e arresto netto finale.","k":1,"w":"La lassità a 30° con arresto netto indica una lesione del LCM non completa: è il test che definisce il grado.","a":"valgo stress collaterale grado"},{"c":7,"l":"Test di Lachman","t":"Traslazione anteriore simmetrica con arresto netto a destra e a sinistra.","k":1,"w":"La scheda chiede di cercare lesioni del LCA associate: con lo stesso meccanismo in valgo il LCA va sempre escluso.","a":"lachman crociato anteriore"},{"c":7,"l":"Cassetto anteriore","t":"Negativo, simmetrico.","a":"anterior drawer cassetto"},{"c":7,"l":"Cassetto posteriore e sag sign","t":"Negativi.","a":"posteriore sag"},{"c":7,"l":"Stress in varo a 0° e 30°","t":"Negativo.","a":"varo laterale"},{"c":7,"l":"Test meniscali (McMurray, Thessaly)","t":"McMurray: dolore mediale aspecifico in rotazione esterna, senza click. Thessaly non eseguito per il dolore in carico.","a":"mcmurray thessaly menisco"},{"c":8,"l":"Radiografia del ginocchio","t":"Nessuna frattura né distacco osseo all'inserzione del LCM.","a":"radiografia rx"},{"c":8,"l":"Risonanza magnetica","t":"Lesione parziale (II grado) delle fibre superficiali del LCM vicino all'inserzione femorale, con edema dei tessuti molli. LCA e LCP integri, menischi integri, angolo postero-mediale integro, nessuna contusione ossea significativa.","k":1,"w":"Conferma che la lesione è isolata: con LCA, menisco e angolo postero-mediale integri il percorso resta conservativo.","a":"risonanza rm rmn"}]},
{"id":"ginocchio-uscita","d":"Ginocchio","t":"Estremo, 19 anni, ginocchio dopo un cambio di direzione","chips":["19 anni","Estremo (15)","Serie A2","1,81 m · 82 kg","Ginocchio sinistro"],"testo":"Filippo ha 19 anni ed è l'estremo della prima squadra in serie A2. Giovedì, in allenamento, ha piantato il piede sinistro per cambiare direzione verso destra, senza essere toccato. Ha sentito il ginocchio «uscire» e poi «rientrare da solo» appena l'ha disteso, ed è caduto a terra. Il ginocchio si è gonfiato molto in poche ore. Oggi è lunedì e viene da te con le stampelle, caricando poco a sinistra.","diag":"Prima lussazione laterale traumatica della rotula sinistra, ridotta spontaneamente: lesione del legamento femoro-rotuleo mediale (MPFL) all'inserzione femorale, emartro, edema osseo da impatto sulla faccetta mediale della rotula e sul condilo femorale laterale, piccola lesione condrale della faccetta mediale (circa 0,5 cm²) senza frammenti liberi. Displasia trocleare lieve, TT-TG e altezza rotulea nella norma, cartilagini di accrescimento chiuse; LCA e LCM integri. Due fattori di rischio di recidiva (età giovane, displasia trocleare): percorso conservativo, con decisione su eventuale chirurgia condivisa con l'ortopedico.","schede":[["lussazione-rotula","Lussazione e instabilità di rotula"]],"items":[{"c":0,"l":"Meccanismo del trauma","t":"«Ho piantato il sinistro per scartare verso destra, il ginocchio è andato verso l'interno e il corpo ha girato sopra. Nessuno mi ha toccato, era un esercizio senza contatto.»","k":1,"w":"Più il trauma è lieve, più pesano i fattori anatomici predisponenti: una lussazione da semplice cambio di direzione fa pensare a un'anatomia sfavorevole.","s":"Blønd 2025 (PMID 39976176)","a":"dinamica cambio direzione"},{"c":0,"l":"Cosa ha sentito al momento","t":"«Ho visto la rotula spostata verso l'esterno, il ginocchio era storto. Appena ho steso la gamba è rientrata da sola con un rumore sordo.»","k":1,"w":"La rotula che esce lateralmente e si riduce estendendo il ginocchio è il racconto tipico della lussazione; lo stesso meccanismo però può rompere il LCA, che va escluso.","a":"rotula uscita rientrata lussazione"},{"c":0,"l":"Comparsa del gonfiore","t":"«In due ore il ginocchio era diventato enorme, non riuscivo più a piegarlo.»","k":1,"w":"Un gonfiore rapido e grande indica un emartro: con la lussazione fa sospettare una lesione osteocondrale e porta a chiedere la risonanza il prima possibile.","s":"Blønd 2025 (PMID 39976176)","a":"gonfiore versamento emartro"},{"c":0,"l":"Blocchi da giovedì","t":"«Non si è mai bloccato. Faccio fatica a stenderlo del tutto, ma è per il gonfiore, non sento qualcosa che si incastra.»","k":1,"w":"Un ginocchio bloccato o impossibile da estendere dopo la riduzione fa sospettare un frammento osteocondrale libero e richiede imaging rapido.","a":"blocco incastro frammento"},{"c":0,"l":"Episodi precedenti","t":"«È la prima volta. Non avevo mai avuto la sensazione che la rotula si spostasse, nemmeno piccoli cedimenti.»","k":1,"w":"Distinguere prima lussazione e instabilità recidivante cambia il percorso: la ricostruzione del MPFL è indicata soprattutto nelle recidive.","a":"primo episodio recidiva precedenti"},{"c":0,"l":"Ginocchio controlaterale e familiarità","t":"«Il destro non mi ha mai dato problemi. Mia sorella ha avuto la rotula uscita due volte giocando a pallavolo.»","k":1,"w":"Età, familiarità, sintomi in entrambe le ginocchia e meccanismo sono gli elementi anamnestici che contano dopo una prima lussazione.","s":"Blønd 2025 (PMID 39976176)","a":"familiarità sorella controlaterale bilaterale"},{"c":0,"l":"Dolore","t":"«A riposo 3/10, se provo a piegarlo 6/10. Fa male soprattutto sul lato interno della rotula.»","a":"vas nrs dolore"},{"c":0,"l":"Cosa è stato fatto finora","t":"«Il preparatore mi ha messo ghiaccio e una ginocchiera. Mi hanno detto di usare le stampelle. Nessun esame finora.»","a":"trattamenti ghiaccio ginocchiera"},{"c":0,"l":"Salute generale e farmaci","t":"«Sto bene, nessuna malattia. Paracetamolo la sera.»","a":"salute farmaci"},{"c":1,"l":"Ispezione del ginocchio","t":"Ginocchio sinistro molto gonfio, profili della rotula non visibili. Ecchimosi sul lato mediale, tra rotula ed epicondilo mediale. Ginocchio tenuto flesso di circa 15°.","a":"ispezione gonfiore ecchimosi"},{"c":1,"l":"Stroke test (versamento)","t":"Grado 3+: non si riesce a spostare il liquido dal lato mediale. A destra assente.","a":"versamento stroke effusione"},{"c":1,"l":"Posizione della rotula e allineamento","t":"A destra rotula in asse; in piedi lieve valgo bilaterale delle ginocchia. A sinistra posizione poco valutabile per il versamento.","a":"allineamento valgo rotula alta"},{"c":1,"l":"Cammino con stampelle","t":"Carico parziale a sinistra, ginocchio rigido e flesso in tutto l'appoggio.","a":"andatura stampelle"},{"c":2,"l":"Sensibilità di gamba e piede","t":"Normale e simmetrica.","a":"neurologico sensibilità"},{"c":2,"l":"Polsi distali e polpaccio","t":"Pedidio e tibiale posteriore presenti. Polpaccio morbido, non gonfio, non dolente.","a":"vascolare polsi trombosi"},{"c":3,"l":"Palpazione del retinacolo mediale e dell'inserzione femorale del MPFL","t":"Dolore vivo 7/10 vicino al tubercolo dell'adduttore, sul tratto femorale del legamento; meno sul bordo mediale della rotula.","k":1,"w":"Localizza la lesione dei freni mediali; il tipo di lesione del MPFL però non è risultato associato alla recidiva.","s":"Huntington 2019 (PMID 31825650)","a":"mpfl retinacolo mediale adduttore"},{"c":3,"l":"Palpazione del condilo femorale laterale","t":"Dolore 4/10 sulla parte laterale del condilo.","a":"condilo laterale contusione"},{"c":3,"l":"Palpazione del LCM","t":"Non dolente all'inserzione femorale né tibiale.","a":"collaterale mediale"},{"c":3,"l":"Palpazione di tendine rotuleo e quadricipitale","t":"Non dolenti, nessun avvallamento.","a":"tendine rotuleo quadricipitale"},{"c":4,"l":"Estensione e flessione del ginocchio","t":"Estensione: sinistra -10°, destra +3°. Flessione: sinistra 80° con dolore e tensione da versamento, destra 145°.","k":1,"w":"Il deficit di ROM qui dipende dal versamento: va seguito nel tempo, e il ROM completo e simmetrico è un criterio per avanzare e per il rientro.","a":"rom estensione flessione goniometro"},{"c":5,"l":"Estensione attiva contro gravità","t":"Da seduto solleva la gamba e la tiene contro gravità, con un lag di 10°.","k":1,"w":"Se non riuscisse a estendere attivamente contro gravità andrebbe esclusa una rottura del tendine rotuleo o quadricipitale; il lag misura l'inibizione del quadricipite.","a":"estensione attiva lag quadricipite"},{"c":5,"l":"Forza del quadricipite al dinamometro (ginocchio a 90°)","t":"Sinistra 17 kg, limitata da dolore e versamento; destra 43 kg. Poco affidabile oggi, va ripetuta.","a":"dinamometro hhd quadricipite"},{"c":5,"l":"Forza di abduttori ed extrarotatori d'anca al dinamometro","t":"Abduttori: sinistra 22 kg, destra 24 kg. Extrarotatori: sinistra 14 kg, destra 15 kg.","k":1,"w":"Forza di quadricipite e anca è la base del percorso e un criterio di passaggio tra le fasi (LSI almeno 80%, poi 90%, come proposta operativa della scheda).","a":"abduttori extrarotatori anca glutei"},{"c":6,"l":"Squat e appoggio monopodalico","t":"Squat bipodalico solo fino a 30° con carico a destra. Monopodalico a sinistra non eseguibile.","a":"squat monopodalico"},{"c":7,"l":"Apprehension test di Fairbank","t":"Positivo: alla spinta laterale della rotula a 30° di flessione contrae il quadricipite e ferma la mano dell'esaminatore.","k":1,"w":"È il test classico per l'instabilità di rotula ed è anche un criterio di rientro, ma nella scheda non ci sono studi solidi sulla sua accuratezza.","a":"apprensione fairbank apprehension"},{"c":7,"l":"Scorrimento laterale della rotula","t":"Aumentato a sinistra rispetto a destra, con dolore mediale.","a":"scorrimento laterale glide lassità"},{"c":7,"l":"J-sign","t":"Non valutabile oggi per il versamento; a destra assente.","a":"jsign tracking"},{"c":7,"l":"Test di Lachman","t":"Traslazione anteriore simmetrica con arresto netto.","k":1,"w":"Il LCA con emartro ha lo stesso meccanismo ed è il differenziale da non perdere.","a":"lachman crociato anteriore"},{"c":7,"l":"Stress in valgo a 0° e 30°","t":"Stabile, senza dolore sul LCM.","k":1,"w":"Una lassità al valgo indicherebbe una lesione associata del LCM.","a":"valgo stress collaterale"},{"c":7,"l":"Test meniscali (McMurray)","t":"Non eseguibile per versamento e flessione limitata.","a":"mcmurray menisco"},{"c":8,"l":"Radiografia (antero-posteriore, laterale, assiale)","t":"Rotula in sede, nessuna frattura, nessun frammento osseo libero visibile. Cartilagini di accrescimento chiuse.","k":1,"w":"Le cartilagini di accrescimento aperte sono un fattore di rischio di recidiva: qui sono chiuse.","s":"Huntington 2019 (PMID 31825650)","a":"radiografia rx cartilagini accrescimento"},{"c":8,"l":"Risonanza magnetica","t":"Lesione del MPFL all'inserzione femorale, edema osseo della faccetta mediale della rotula e del condilo femorale laterale, piccola lesione condrale della faccetta mediale di circa 0,5 cm² senza frammenti liberi. Displasia trocleare lieve. TT-TG 13 mm, indice di Caton-Deschamps 1,1. LCA e LCM integri.","k":1,"w":"Il consenso la considera necessaria dopo la prima lussazione per vedere displasia trocleare, rotula alta e lesioni osteocondrali; le lesioni di almeno 1 cm² nella zona di contatto vanno riparate (qui è più piccola). Con due fattori di rischio (età giovane, displasia trocleare) la recidiva stimata è tra il 29,6% e il 60,2%.","s":"Blønd 2025 (PMID 39976176); Balcarek 2025 (PMID 40053919); Huntington 2019 (PMID 31825650)","a":"risonanza rm rmn displasia osteocondrale"}]},
{"id":"coscia-calcio","d":"Muscoli","t":"Apertura, 23 anni, coscia anteriore mentre calcia","chips":["23 anni","Apertura (10)","Serie A2","1,79 m · 82 kg","Coscia destra"],"testo":"Matteo è il mediano di apertura di una squadra di serie A2 ed è il calciatore designato. Ieri sera, alla fine dell'allenamento, durante una serie di calci in touche ha sentito una fitta improvvisa davanti alla coscia destra, la gamba con cui calcia. Ha smesso subito e ha messo ghiaccio. Non ha fatto esami. Oggi viene da te camminando, con un passo un po' più corto a destra.","diag":"Lesione acuta da calcio del retto femorale destro (gamba di calcio), in sede intramuscolare: aponeurosi centrale nel terzo prossimale, senza interruzione completa dell'aponeurosi. Tendine prossimale e inserzione sulla spina iliaca antero-inferiore integri: avulsione esclusa. Contusione, patologia dell'anca e dolore inguinale da ileopsoas o adduttori esclusi. Tempi orientativi intorno ai 34 giorni (dato medio per l'aponeurosi centrale), rientro guidato dai criteri con progressione completa del calcio.","schede":[["lesione-retto-femorale","Lesione del retto femorale"]],"items":[{"c":0,"l":"Meccanismo","t":"«Ultimo esercizio dell'allenamento, calci in touche. Ho portato la gamba destra indietro per caricare e, nel momento di calciare forte, ho sentito una fitta davanti alla coscia, in alto, come un colpo secco. Nessun contatto con nessuno.»","k":1,"w":"Il calcio è uno dei due meccanismi tipici: il retto femorale è al massimo dell'allungamento (anca estesa, ginocchio flesso) e subito dopo deve contrarsi in modo esplosivo.","s":"Mullen 2025 (PMID 41248256); Mendiguchia 2012 (PMID 22864009)","a":"dinamica calcio calciare caricamento"},{"c":0,"l":"Schiocco e capacità di continuare","t":"«Ho sentito come uno schiocco. Ho provato a fare un altro calcio, ma non ci riuscivo: la gamba non partiva. Ho smesso.»","k":1,"w":"Dolore anteriore improvviso con schiocco è la presentazione tipica; l'impossibilità di calciare indica una lesione da valutare con forza e palpazione per escludere una rottura completa.","s":"Mullen 2025 (PMID 41248256)","a":"schiocco strappo continuare"},{"c":0,"l":"Momento della seduta e fatica","t":"«Era la fine, avevo già calciato tanto: forse 40-50 calci tra piazzati e touche. Il riscaldamento l'avevamo fatto un'ora e mezza prima.»","a":"fatica riscaldamento"},{"c":0,"l":"Dolore e andamento","t":"«Ieri sera 7/10. Oggi a riposo 2/10, camminando veloce e salendo le scale 4/10.»","a":"intensità andamento"},{"c":0,"l":"Lesioni precedenti","t":"«Due stagioni fa uno stiramento dietro la coscia destra. L'anno scorso un fastidio davanti alla stessa coscia, dieci giorni fermo, senza esami e senza riabilitazione specifica.»","k":1,"w":"Una precedente lesione del retto femorale o degli hamstring è tra i fattori di rischio riportati; le recidive causano assenze più lunghe.","s":"Begum 2020 (PMID 33312709); Ekstrand 2011 (PMID 21335353)","a":"storia pregressa recidiva stiramento"},{"c":0,"l":"Gamba dominante e volume di calcio","t":"«Calcio di destro: piazzati, drop e touche. Di solito calcio tre volte a settimana, 60-80 calci a seduta. Ero stato fermo due settimane per la caviglia sinistra e martedì, al rientro, ho calciato subito tanto.»","k":1,"w":"La gamba dominante è un fattore di rischio riportato; il picco di volume di calci dopo una pausa è ciò che la prevenzione della scheda suggerisce di evitare (proposta operativa).","s":"Begum 2020 (PMID 33312709)","a":"dominante volume calciatore piazzati pausa"},{"c":0,"l":"Terreno","t":"«Campo in erba duro e secco, non piove da settimane.»","a":"terreno campo secco"},{"c":0,"l":"Colpi diretti alla coscia","t":"«Nessun colpo, nessuna ginocchiata, né ieri né nei giorni prima.»","k":1,"w":"Esclude la contusione da colpo diretto, la principale diagnosi differenziale, che ha un percorso diverso e il rischio di sindrome compartimentale.","a":"contusione colpo ginocchiata diretto"},{"c":0,"l":"Inguine, schiena e salute generale","t":"«Prima di ieri nessun dolore all'inguine né alla schiena. Niente febbre, sto bene.»","a":"inguine lombare febbre generale"},{"c":1,"l":"Ispezione della coscia","t":"Nessun ematoma visibile, nessuna deformità. Nessun avvallamento né massa che si sposta quando contrae. Circonferenza a 15 cm dalla rotula: destra 56,5 cm, sinistra 56,0 cm.","a":"avvallamento deformità ematoma circonferenza"},{"c":1,"l":"Cammino","t":"Passo più corto a destra, anca destra meno estesa a fine appoggio, nessuna zoppia di caduta del bacino.","a":"andatura zoppia passo"},{"c":2,"l":"Sensibilità della coscia","t":"Sensibilità normale e simmetrica sulla faccia anteriore e laterale della coscia.","a":"neurologico dermatomeri parestesie"},{"c":2,"l":"Riflesso rotuleo","t":"Presente e simmetrico.","a":"riflesso rotuleo"},{"c":3,"l":"Palpazione della spina iliaca antero-inferiore e del tendine prossimale","t":"Spina iliaca antero-inferiore non dolente. Tendine prossimale palpabile in continuità, non dolente.","k":1,"w":"Esclude l'avulsione e la lesione del tendine prossimale: hanno tempi più lunghi (tendine libero prossimale in media circa 50 giorni) e, nell'avulsione, il conservativo è poco affidabile e la chirurgia è un'opzione.","s":"Begum 2020 (PMID 33312709); Pietsch 2026 (PMID 42661294)","a":"avulsione spina iliaca apofisi inserzione prossimale"},{"c":3,"l":"Sede del punto più doloroso","t":"Dolore profondo al centro della coscia anteriore, a circa 14 cm sotto la spina iliaca antero-inferiore, nel terzo prossimale del ventre.","k":1,"w":"Localizza la sede: un dolore profondo e centrale fa pensare all'aponeurosi centrale, la lesione «muscolo nel muscolo». La sede orienta i tempi.","s":"Pietsch 2026 (PMID 42661294)","a":"localizzazione palpazione doloroso intramuscolare aponeurosi"},{"c":3,"l":"Lunghezza della zona dolente","t":"Circa 7 cm in senso longitudinale.","a":"estensione lunghezza"},{"c":3,"l":"Vuoto palpabile","t":"Nessun vuoto lungo il tendine e il ventre; in contrazione il muscolo è in continuità.","k":1,"w":"Un vuoto palpabile o una perdita netta di forza fanno sospettare una rottura completa: in quel caso RM e valutazione ortopedica rapida.","a":"rottura completa difetto"},{"c":3,"l":"Palpazione di ileopsoas e adduttori","t":"Non dolenti, inserzioni degli adduttori sul pube non dolenti.","a":"ileopsoas adduttori inguine pube"},{"c":4,"l":"Flessione del ginocchio da prono","t":"Destra 110° con dolore anteriore alla coscia e bacino che si solleva dal lettino; sinistra 140° senza dolore.","k":1,"w":"Dolore e ROM ridotto rispetto al lato sano servono a monitorare il recupero e sono un criterio di rientro: il calcio porta il retto femorale nel massimo allungamento.","a":"prono allungamento flessibilità ely"},{"c":4,"l":"Thomas test modificato","t":"Destra: coscia in linea con il lettino, ginocchio flesso a 45° con dolore anteriore. Sinistra: coscia 10° sotto l'orizzontale, ginocchio flesso a 70°.","a":"thomas modificato"},{"c":4,"l":"Mobilità dell'anca","t":"Flessione e rotazioni complete e indolori; rotazione interna 35° a destra e a sinistra.","a":"rotazione interna mobilità anca"},{"c":5,"l":"Estensione del ginocchio al dinamometro, seduto a 90°","t":"Destra 28 kg con dolore 3/10; sinistra 41 kg. LSI 68%.","k":1,"w":"Dolore e deficit rispetto al lato sano (LSI) servono a monitorare e sono un criterio di rientro; la soglia del 90% è una proposta operativa.","a":"dinamometro quadricipite isometrica estensione"},{"c":5,"l":"Estensione del ginocchio in posizione allungata","t":"Con l'anca più estesa la contrazione non è tollerata: dolore 6/10 già a sforzo submassimale.","a":"allungata posizione allungamento"},{"c":5,"l":"Flessione d'anca al dinamometro","t":"Da seduto, ginocchio flesso: destra 18 kg con dolore 4/10, sinistra 30 kg (LSI 60%). Da supino: destra 14 kg con dolore, sinistra 22 kg.","k":1,"w":"La flessione d'anca esplosiva è il cuore del calcio. Il deficit è doloroso ma la forza c'è: una perdita netta di forza farebbe sospettare una rottura completa.","a":"flessione anca dinamometro flessori"},{"c":5,"l":"Forza di hamstring e glutei","t":"Conservata e indolore, simmetrica.","a":"ischiocrurali glutei hamstring"},{"c":6,"l":"Squat e affondo","t":"Squat bilaterale completo e indolore. Affondo con la gamba destra dietro: dolore 4/10 a fine discesa.","a":"affondo squat"},{"c":6,"l":"Appoggio monopodalico nella posizione del calcio","t":"In appoggio sulla sinistra, oscillazione della destra indietro e avanti: dolore anteriore nella fase di caricamento, bacino stabile.","a":"monopodalico oscillazione controllo bacino"},{"c":6,"l":"Jogging e calcio","t":"Non eseguibili oggi: la camminata veloce dà già dolore.","a":"corsa jogging sprint"},{"c":7,"l":"Test dell'anca (FADIR e FABER)","t":"Negativi a destra e a sinistra.","k":1,"w":"Escludono una patologia dell'anca, una delle diagnosi differenziali del dolore anteriore alto.","a":"fadir faber impingement"},{"c":7,"l":"Test neurodinamico del nervo femorale","t":"Slump in decubito laterale: i sintomi non cambiano con la flessione e l'estensione del collo. Negativo.","a":"neurodinamico femorale slump"},{"c":8,"l":"Radiografia del bacino","t":"Non richiesta: a 23 anni le cartilagini di accrescimento sono chiuse e la spina iliaca antero-inferiore non è dolente.","k":1,"w":"Nell'adolescente con dolore acuto sulla spina iliaca antero-inferiore dopo un calcio va chiesta per escludere l'avulsione apofisaria; nell'adulto con quell'area indolore non serve.","a":"radiografia apofisaria apofisi raggi"},{"c":8,"l":"Ecografia","t":"Area ipoecogena intramuscolare centrale nel terzo prossimale, lungo l'aponeurosi centrale.","a":"ecografia"},{"c":8,"l":"Risonanza magnetica","t":"Lesione dell'aponeurosi centrale del retto femorale destro nel terzo prossimale, edema esteso 8 cm in senso cranio-caudale, senza interruzione completa dell'aponeurosi. Tendine prossimale e inserzione sulla spina iliaca antero-inferiore integri, nessuna avulsione.","k":1,"w":"La RM è l'esame di scelta per sede ed estensione. L'aponeurosi centrale richiede in media circa 34 giorni, di più se interrotta; nessun dato RM ha predetto la recidiva.","s":"Mullen 2025 (PMID 41248256); Pietsch 2026 (PMID 42661294)","a":"risonanza magnetica"}]},
{"id":"schiena-giovane","d":"Colonna","t":"Terza linea, 16 anni, mal di schiena da settimane","chips":["16 anni","Terza linea (8)","Under 17","1,84 m · 84 kg","Lombare sinistra"],"testo":"Filippo è un numero 8 dell'Under 17. Da circa cinque settimane ha dolore nella parte bassa della schiena, a sinistra. È iniziato senza un trauma preciso, nel periodo in cui la squadra ha aumentato le mischie al macchinario e il lavoro in palestra. Continua ad allenarsi, ma il dolore aumenta dopo mischie, placcaggi e sollevamenti. Viene da te un lunedì, due giorni dopo la partita.","diag":"Spondilolisi da stress della pars interarticularis sinistra di L5 in stadio precoce (edema osseo alla RM, linea di frattura sottile e incompleta), unilaterale, senza spondilolistesi. Nessun deficit neurologico e nessuna red flag. Escluse origine radicolare o discale e sacroiliaca. Gestione conservativa: stop da mischia, placcaggio, sollevamenti e gesti in estensione e rotazione, poi riabilitazione per fasi; rientro orientativo dopo circa 3 mesi, guidato dai criteri e dal via libera del medico.","schede":[["colonna-spondilolisi","Spondilolisi nell'atleta giovane"]],"items":[{"c":0,"l":"Esordio e andamento","t":"«Cinque settimane fa, piano piano, senza un momento preciso. All'inizio solo dopo gli allenamenti, adesso anche durante, e il giorno dopo la partita è peggio.»","k":1,"w":"Dolore lombare insidioso da settimane in un adolescente sportivo: è il quadro in cui sospettare la spondilolisi. Una diagnosi tempestiva aumenta la probabilità di guarigione ossea.","a":"esordio insorgenza andamento"},{"c":0,"l":"Attività che peggiorano e che migliorano","t":"«Peggiora in mischia, quando spingo e la schiena va indietro, nei placcaggi, negli stacchi e negli squat in palestra e quando sollevo il saltatore in touche. Piegarmi in avanti non mi fa male. Se sto fermo due giorni va meglio.»","k":1,"w":"Dolore con carichi ripetuti in estensione e rotazione è il meccanismo tipico della lesione della pars; la flessione indolore orienta lontano da un'origine discale.","a":"estensione mischia placcaggio sollevamento touche"},{"c":0,"l":"Sede del dolore","t":"«Qui.» Indica con un dito un punto sotto la cintura, a sinistra, a circa 2 cm dalla linea mediana.","k":1,"w":"Un dolore lombare basso, localizzato e unilaterale è tipico della lesione della pars, più spesso a L5.","a":"localizzazione unilaterale"},{"c":0,"l":"Irradiazione e sintomi alle gambe","t":"«Non scende nella gamba, niente formicolii né debolezza.»","k":1,"w":"Un deficit neurologico o sintomi radicolari (L5) sono una red flag da invio urgente: vanno chiesti e poi verificati con l'esame neurologico.","a":"irradiazione formicolio sciatica gamba radicolare"},{"c":0,"l":"Dolore notturno, febbre e calo di peso","t":"«Dormo bene, il dolore di notte non c'è. Niente febbre, il peso è stabile, anzi sono aumentato con la palestra.»","k":1,"w":"Dolore notturno costante, febbre o calo ponderale fanno escludere tumore o infezione.","a":"notturno febbre ponderale tumore infezione"},{"c":0,"l":"Sfinteri e sensibilità perineale","t":"«Nessun problema a urinare né ad andare in bagno, nessun formicolio in zona genitale.»","k":1,"w":"Le alterazioni sfinteriche sono una red flag da invio urgente.","a":"sfinteri vescica perineale cauda"},{"c":0,"l":"Crescita","t":"«Nell'ultimo anno sono cresciuto di 7 centimetri.»","k":1,"w":"La lesione è più frequente durante la crescita, quando l'osso della pars è più vulnerabile.","a":"crescita accrescimento altezza"},{"c":0,"l":"Carico di allenamento","t":"«Quattro allenamenti a settimana più la partita. Da settembre abbiamo aggiunto due sedute di palestra con stacchi e squat e la mischia al macchinario due volte a settimana.»","a":"carico allenamenti palestra macchinario"},{"c":0,"l":"Traumi","t":"«Nessuna caduta e nessun colpo particolare alla schiena.»","a":"trauma caduta"},{"c":0,"l":"Farmaci","t":"«Ogni tanto un ibuprofene dopo la partita, aiuta un po'.»","a":"farmaci ibuprofene antinfiammatori"},{"c":1,"l":"Postura in piedi","t":"Lordosi lombare lievemente aumentata, bacino in antiversione. Nessuno scalino visibile tra i processi spinosi, nessuna scoliosi evidente.","a":"postura lordosi scoliosi"},{"c":1,"l":"Cammino","t":"Normale.","a":"andatura"},{"c":2,"l":"Sensibilità degli arti inferiori","t":"Normale e simmetrica nei territori da L2 a S1.","a":"sensibilità dermatomeri neurologico"},{"c":2,"l":"Riflessi","t":"Rotuleo e achilleo presenti e simmetrici.","a":"riflessi rotuleo achilleo"},{"c":3,"l":"Palpazione e percussione dei processi spinosi L4-L5-S1","t":"Dolore alla pressione su L5 e subito a sinistra del processo spinoso. Nessuno scalino palpabile.","k":1,"w":"La dolorabilità focale è compatibile con la lesione della pars; uno scalino palpabile farebbe sospettare una spondilolistesi.","a":"palpazione percussione spinosi scalino"},{"c":3,"l":"Palpazione dei paravertebrali","t":"Muscoli paravertebrali lombari tesi da entrambi i lati, più a sinistra, lievemente dolenti.","a":"paravertebrali contrattura muscoli"},{"c":3,"l":"Palpazione della sacroiliaca","t":"Non dolente a destra e a sinistra.","a":"sacroiliaca"},{"c":4,"l":"Flessione lombare","t":"Completa, arriva con le dita a terra, indolore.","k":1,"w":"Flessione indolore e dolore in estensione: un quadro meno compatibile con un'origine discale, utile per la diagnosi differenziale.","a":"flessione lombare disco"},{"c":4,"l":"Estensione lombare in piedi","t":"Limitata a circa metà dell'ampiezza attesa, dolore 6/10 lombare basso a sinistra.","k":1,"w":"Il dolore lombare localizzato in estensione è compatibile con la lesione della pars, ma non specifico: da solo non basta.","a":"estensione lombare piedi"},{"c":4,"l":"Estensione combinata con rotazione (quadrante)","t":"Verso sinistra dolore 7/10 nello stesso punto; verso destra 3/10.","a":"quadrante rotazione kemp"},{"c":4,"l":"Lunghezza degli hamstring","t":"Angolo popliteo: mancano 45° all'estensione a destra e 48° a sinistra. SLR passivo 55° da entrambi i lati, con tensione dietro la coscia e nessun sintomo lombare o alla gamba.","k":1,"w":"La rigidità degli ischiocrurali è frequente come risposta protettiva; un SLR senza sintomi radicolari è coerente con l'assenza di compromissione della radice.","a":"angolo popliteo ischiocrurali hamstring lasegue"},{"c":4,"l":"Flessori d'anca e mobilità dell'anca","t":"Thomas test: flessori d'anca rigidi da entrambi i lati, coscia sopra l'orizzontale. Rotazioni d'anca complete.","a":"thomas flessori mobilità anca"},{"c":5,"l":"Forza per miotomi da L2 a S1","t":"5/5 e simmetrica, compresi l'estensione dell'alluce e la dorsiflessione della caviglia.","k":1,"w":"Completa l'esame neurologico: una debolezza nel territorio di L5 sarebbe una red flag da invio urgente.","a":"miotomi debolezza alluce dorsiflessione"},{"c":5,"l":"Resistenza del tronco","t":"Side plank: 45 s a destra, 40 s a sinistra. Test di resistenza degli estensori: interrotto a 35 s per dolore lombare.","a":"plank sorensen resistenza tronco estensori"},{"c":5,"l":"Ponte e glutei","t":"Ponte monopodalico: 15 ripetizioni per lato, a destra e a sinistra, senza dolore.","a":"ponte glutei bridge"},{"c":6,"l":"Hip hinge a corpo libero","t":"Perde la posizione neutra: a fine movimento risale estendendo la lombare invece che le anche.","a":"hinge stacco controllo"},{"c":6,"l":"Posizione di mischia simulata","t":"Posizione di spinta contro il muro indolore; la spinta con estensione finale del tronco dà dolore 5/10.","a":"mischia spinta"},{"c":7,"l":"Stork test (one-leg hyperextension)","t":"In appoggio sulla sinistra: dolore 7/10 lombare sinistro. In appoggio sulla destra: 2/10.","k":1,"w":"Positivo dal lato del dolore, ma la sua accuratezza diagnostica è bassa: non basta per confermare né per escludere, quindi serve l'imaging.","s":"Alqarni 2015 (PMID 25797410)","a":"stork monopodalica iperestensione"},{"c":7,"l":"Slump test","t":"Negativo: nessun sintomo neurale.","a":"slump neurodinamico"},{"c":7,"l":"Test di provocazione sacroiliaca","t":"Negativi.","a":"sacroiliaci provocazione"},{"c":8,"l":"Radiografia","t":"Non eseguita: il medico ha scelto la RM come primo esame.","a":"radiografia raggi"},{"c":8,"l":"Risonanza magnetica lombare","t":"Edema osseo della pars interarticularis sinistra di L5 con linea di frattura sottile e incompleta. Pars destra normale. Nessuno scivolamento vertebrale. Dischi e radici nella norma.","k":1,"w":"La RM è il primo esame indicato: nessuna radiazione e vede l'edema. Una lesione precoce, con edema, ha più probabilità di guarire con lo stop dallo sport; la gestione conservativa dà buoni esiti nella maggior parte dei casi.","s":"Klein 2009 (PMID 19352240)","a":"risonanza magnetica edema"},{"c":8,"l":"TC","t":"Non richiesta per ora: il medico la valuterà al controllo se servirà definire meglio la frattura.","a":"tomografia computerizzata"}]}
];
